import { DIAGRAM_TYPES, type DiagramTypeInfo } from './registry'

/**
 * Diagram-type detection.
 *
 * There is exactly one implementation of this in the repository. The application, the
 * editor and the renderer all call it, so "what kind of diagram is this" can only ever
 * have one answer. Three divergent answers is a defect class we refuse to have.
 */

const FRONTMATTER = /^\s*---\r?\n[\s\S]*?\r?\n---\r?\n?/
const DIRECTIVE = /%%\{[\s\S]*?\}%%/g
const LINE_COMMENT = /^\s*%%(?!\{)[^\n]*$/gm

/**
 * Strips everything that may legally precede the diagram header: YAML frontmatter, init
 * directives and `%%` comments.
 */
export function stripPreamble(text: string): string {
  return text
    .replace(FRONTMATTER, '')
    .replace(DIRECTIVE, '')
    .replace(LINE_COMMENT, '')
    .replace(/^\s*[\r\n]+/, '')
}

/** The first meaningful line of a document — the one carrying the diagram header. */
export function headerLine(text: string): string {
  const stripped = stripPreamble(text)
  for (const line of stripped.split(/\r?\n/)) {
    if (line.trim().length > 0) return line
  }
  return ''
}

/**
 * Returns the diagram type, or `undefined` when the text has no recognizable header.
 *
 * Order follows `DIAGRAM_TYPES`, mirroring upstream detector registration order: `-v2`
 * and `-elk` variants are tested before their base forms, which would otherwise swallow
 * them.
 */
export function detectDiagramType(text: string): DiagramTypeInfo | undefined {
  const header = headerLine(text)
  if (header === '') return undefined
  for (const type of DIAGRAM_TYPES) {
    for (const pattern of type.detect) {
      if (pattern.test(header)) return type
    }
  }
  return undefined
}

