import { z } from 'zod'

/**
 * Normalized render errors.
 *
 * Mermaid's raw parser output is frequently unhelpful to a user. It is normalized here
 * into something placeable in the editor gutter, with the original kept behind `raw` for
 * a developer panel — never for product UI.
 */

export const renderErrorKind = z.enum([
  /** The text has no recognizable diagram header. */
  'unknown-diagram-type',
  /** The parser rejected the document. */
  'parse',
  /** Parsed, but rendering failed. */
  'render',
  /** The diagram type requires a newer mermaid than the pinned runtime. */
  'unsupported-version',
  /** The type ships separately and has not been registered. */
  'external-diagram-not-registered',
  /** The render frame did not answer in time. */
  'timeout',
  /** Anything unclassified. Carries `raw` so it can be classified later. */
  'unknown',
])

export type RenderErrorKind = z.infer<typeof renderErrorKind>

export const renderErrorSchema = z.object({
  kind: renderErrorKind,
  /** Actionable, user-facing. Never Mermaid's raw text. */
  message: z.string(),
  line: z.number().int().positive().optional(),
  column: z.number().int().nonnegative().optional(),
  /** The offending source line, for display next to the message. */
  excerpt: z.string().optional(),
  /** Mermaid's original text. Developer panel only. */
  raw: z.string().optional(),
})

export type RenderError = z.infer<typeof renderErrorSchema>

