import { describe, expect, test } from 'bun:test'
import { detectDiagramType, headerLine, stripPreamble } from './detect'
import { DIAGRAM_TYPES } from './registry'

describe('registry', () => {
  test('ids are unique', () => {
    const ids = DIAGRAM_TYPES.map((t) => t.id)
    expect(new Set(ids).size).toBe(ids.length)
  })

  test('covers every documented syntax page plus the undocumented info type', () => {
    // 32 documented diagram types (examples.md is not a type) + info.
    expect(DIAGRAM_TYPES.length).toBe(33)
    expect(DIAGRAM_TYPES.filter((t) => t.doc !== null).length).toBe(32)
  })
})

describe('detectDiagramType', () => {
  // The load-bearing test. If two patterns collide, or the order regresses so a base
  // form swallows a variant, this fails.
  for (const type of DIAGRAM_TYPES) {
    test(`detects ${type.id} from its canonical keyword`, () => {
      expect(detectDiagramType(type.keyword)?.id).toBe(type.id)
    })
  }

  const variants: ReadonlyArray<readonly [string, string]> = [
    ['graph TD', 'flowchart'],
    ['flowchart LR', 'flowchart'],
    ['flowchart-elk LR', 'flowchart'],
    ['classDiagram-v2', 'class'],
    ['stateDiagram', 'state'],
    ['stateDiagram-v2', 'state'],
    ['requirement', 'requirement'],
    ['requirementDiagram', 'requirement'],
    ['sankey-beta', 'sankey'],
    ['packet-beta', 'packet'],
    ['block-beta', 'block'],
    ['xychart-beta', 'xychart'],
    ['ishikawa', 'ishikawa'],
    ['railroad-abnf-beta', 'railroad'],
    ['railroad-ebnf-beta', 'railroad'],
    ['railroad-peg-beta', 'railroad'],
    ['railroad-beta', 'railroad'],
    ['C4Container', 'c4'],
  ]

  for (const [text, expected] of variants) {
    test(`detects "${text}" as ${expected}`, () => {
      expect(detectDiagramType(text)?.id).toBe(expected)
    })
  }

  test('returns undefined for empty and unrecognized text', () => {
    expect(detectDiagramType('')).toBeUndefined()
    expect(detectDiagramType('   \n\n  ')).toBeUndefined()
    expect(detectDiagramType('not a diagram')).toBeUndefined()
  })
})

describe('preamble handling', () => {
  test('skips YAML frontmatter', () => {
    const text = '---\ntitle: Hello\nconfig:\n  theme: dark\n---\nflowchart TD\n  A --> B'
    expect(headerLine(text)).toBe('flowchart TD')
    expect(detectDiagramType(text)?.id).toBe('flowchart')
  })

  test('skips init directives', () => {
    const text = "%%{init: {'theme':'forest'}}%%\nsequenceDiagram\n  A->>B: hi"
    expect(detectDiagramType(text)?.id).toBe('sequence')
  })

  test('skips leading comments', () => {
    const text = '%% a note about this diagram\n%% and another\ngantt\n  title X'
    expect(detectDiagramType(text)?.id).toBe('gantt')
  })

  test('skips frontmatter, directive and comments together', () => {
    const text = [
      '---',
      'title: Combined',
      '---',
      "%%{init: {'theme':'dark'}}%%",
      '%% still not the header',
      'erDiagram',
      '  CUSTOMER ||--o{ ORDER : places',
    ].join('\n')
    expect(detectDiagramType(text)?.id).toBe('er')
  })

  test('does not treat a --- separator inside the body as frontmatter', () => {
    const text = 'stateDiagram-v2\n  [*] --> Still\n  Still --> [*]'
    expect(stripPreamble(text)).toBe(text)
  })
})

