import { diagramElementSchema, renderErrorSchema } from '@mr/core'
import { z } from 'zod'

/**
 * The render-frame message contract.
 *
 * Only structured-cloneable values cross this boundary: no functions, no DOM nodes, no
 * class instances. SVG crosses as a string. Both sides validate — the host because the
 * frame runs untrusted diagram text, the frame because it must not trust its embedder
 * blindly either.
 *
 * See docs/architecture/rendering.md.
 */

export const PROTOCOL_VERSION = 1

export const themeVariablesSchema = z.record(z.string(), z.string())

export const renderConfigSchema = z.object({
  /** Forced to 'strict'. Present so drift shows up as a validation failure, not silently. */
  securityLevel: z.literal('strict'),
  theme: z.enum(['base', 'default', 'dark', 'forest', 'neutral']),
  themeVariables: themeVariablesSchema,
  fontFamily: z.string(),
  /** Above this node count the frame answers in coarse mode. */
  coarseThreshold: z.number().int().positive(),
})

export type RenderConfig = z.infer<typeof renderConfigSchema>

export const hostToFrameSchema = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('init'),
    protocol: z.literal(PROTOCOL_VERSION),
  }),
  z.object({
    type: z.literal('render'),
    jobId: z.string(),
    text: z.string(),
    config: renderConfigSchema,
  }),
  z.object({
    type: z.literal('parse'),
    jobId: z.string(),
    text: z.string(),
  }),
  z.object({
    type: z.literal('cancel'),
    jobId: z.string(),
  }),
])

export type HostToFrame = z.infer<typeof hostToFrameSchema>

export const frameToHostSchema = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('ready'),
    protocol: z.literal(PROTOCOL_VERSION),
    mermaidVersion: z.string(),
  }),
  z.object({
    type: z.literal('ok'),
    jobId: z.string(),
    svg: z.string(),
    viewBox: z.object({
      x: z.number(),
      y: z.number(),
      width: z.number(),
      height: z.number(),
    }),
    elements: z.array(diagramElementSchema),
    coarse: z.boolean(),
    durationMs: z.number(),
  }),
  z.object({
    type: z.literal('parsed'),
    jobId: z.string(),
    typeId: z.string().nullable(),
  }),
  z.object({
    type: z.literal('error'),
    jobId: z.string(),
    error: renderErrorSchema,
  }),
])

export type FrameToHost = z.infer<typeof frameToHostSchema>

