    type: z.literal('parsed'),
    jobId: z.string(),
    typeId: z.string().nullable(),
  }),
  z.object({
    type: z.literal('error'),
    jobId: z.string(),
    error: renderErrorSchema,
  }),
])

export type FrameToHost = z.infer<typeof frameToHostSchema>

