import { DIAGRAM_TYPES, type DiagramTypeId } from '@mr/core'
import type { StreamParser } from '@codemirror/language'

/**
 * Dialect registry: one CodeMirror language mode per diagram type.
 *
 * Keywords are not written here by hand. They come from the catalog under
 * `docs/knowledge/diagrams/<id>.md`, which is itself derived from `mermaid-upstream/`.
 * If a dialect and the catalog disagree, the catalog is fixed first.
 *
 * A dialect starts as a StreamParser. It is promoted to a Lezer grammar only when it
 * needs a real syntax tree — folding by block, structural selection, or the phase-3
 * bidirectional visual editor. See docs/architecture/editor.md.
 */

export interface DialectState {
  inLabel: boolean
  lineStart: boolean
}

export interface Dialect {
  readonly id: DiagramTypeId
  readonly parser: StreamParser<DialectState>
  /** Statement keywords offered at the start of a line. */
  readonly statements: readonly string[]
  /** A starter snippet that renders and is genuinely useful, not a two-node stub. */
  readonly starter: string
}

const dialects = new Map<string, Dialect>()

export function registerDialect(dialect: Dialect): void {
  dialects.set(dialect.id, dialect)
}

export function getDialect(id: string): Dialect | undefined {
  return dialects.get(id)
}

export function registeredDialectIds(): readonly string[] {
  return [...dialects.keys()]
}

/** Types in the catalog that still have no dialect. Asserted by a test. */
export function missingDialectIds(): readonly string[] {
  return DIAGRAM_TYPES.filter((t) => !dialects.has(t.id)).map((t) => t.id)
}

