import type { DiagramDocument, Folder, Revision } from '@mr/core'

/**
 * Storage ports.
 *
 * Consumers depend on these, never on IndexedDB. The browser adapter is one
 * implementation; the phase-2 server will be another, and adding it must not change
 * anything above this file. That is the entire reason the indirection exists — do not
 * reach past it "just this once".
 */

export interface ListDocumentsQuery {
  folderId?: string | null
  typeId?: string
  search?: string
  includeDeleted?: boolean
  limit?: number
  cursor?: string
}

export interface Page<T> {
  items: readonly T[]
  nextCursor: string | null
}

export interface DocumentRepository {
  list(query?: ListDocumentsQuery): Promise<Page<DiagramDocument>>
  get(id: string): Promise<DiagramDocument | undefined>
  create(input: Pick<DiagramDocument, 'name' | 'body'> & Partial<DiagramDocument>): Promise<DiagramDocument>
  update(id: string, patch: Partial<DiagramDocument>): Promise<DiagramDocument>
  /** Soft delete. Recoverable until purged. */
  delete(id: string): Promise<void>
  restore(id: string): Promise<DiagramDocument>
  purge(id: string): Promise<void>
}

export interface RevisionRepository {
  append(documentId: string, body: string, label?: string): Promise<Revision>
  list(documentId: string): Promise<readonly Revision[]>
  get(documentId: string, seq: number): Promise<Revision | undefined>
  prune(documentId: string, keep: number): Promise<void>
}

export interface FolderRepository {
  list(): Promise<readonly Folder[]>
  create(input: Omit<Folder, 'id'>): Promise<Folder>
  update(id: string, patch: Partial<Folder>): Promise<Folder>
  delete(id: string): Promise<void>
}

export interface BlobStore {
  put(id: string, data: Blob): Promise<void>
  get(id: string): Promise<Blob | undefined>
  delete(id: string): Promise<void>
  size(id: string): Promise<number>
}

export interface PreferenceStore {
  get<T>(key: string): Promise<T | undefined>
  set<T>(key: string, value: T): Promise<void>
}

export interface StorageQuota {
  usage: number
  quota: number
  persisted: boolean
}

export interface Workspace {
  readonly documents: DocumentRepository
  readonly revisions: RevisionRepository
  readonly folders: FolderRepository
  readonly blobs: BlobStore
  readonly preferences: PreferenceStore
  quota(): Promise<StorageQuota>
  requestPersistence(): Promise<boolean>
}

/** Thrown when a write fails for lack of space. Always recoverable, never silent. */
export class QuotaExceededError extends Error {
  override readonly name = 'QuotaExceededError'
  constructor(readonly quota: StorageQuota) {
    super('Not enough storage space to save this diagram.')
  }
}

