@import 'tailwindcss';

/**
 * One token set for the whole product.
 *
 * These variables drive both the application chrome and the Mermaid `themeVariables`
 * passed to the render frame — see packages/ui/src/theme.ts and
 * docs/architecture/rendering.md. A diagram whose colors do not match the interface is a
 * bug, not a preference, and it is a bug because both read from here.
 */

@theme {
  --font-sans: 'Inter Variable', ui-sans-serif, system-ui, sans-serif;
  --font-mono: 'JetBrains Mono Variable', ui-monospace, monospace;

  --radius-app: 0.5rem;
}

:root {
  color-scheme: light;

  --background: oklch(1 0 0);
  --foreground: oklch(0.19 0.01 265);
  --surface: oklch(0.985 0.002 265);
  --surface-raised: oklch(1 0 0);
  --border: oklch(0.92 0.004 265);
  --border-strong: oklch(0.85 0.006 265);
  --muted: oklch(0.96 0.003 265);
  --muted-foreground: oklch(0.52 0.012 265);

  --primary: oklch(0.55 0.19 265);
  --primary-foreground: oklch(0.99 0 0);
  --accent: oklch(0.7 0.15 195);
  --accent-foreground: oklch(0.19 0.01 265);

  --danger: oklch(0.58 0.21 25);
  --warning: oklch(0.72 0.16 75);
  --success: oklch(0.62 0.15 150);

  --ring: oklch(0.55 0.19 265);

  /* Diagram surface. Read by theme.ts and forwarded to the render frame. */
  --diagram-background: var(--background);
  --diagram-node: oklch(0.97 0.012 265);
  --diagram-node-border: oklch(0.62 0.12 265);
  --diagram-line: oklch(0.55 0.02 265);
  --diagram-text: var(--foreground);
  --diagram-cluster: oklch(0.98 0.006 265);
}

.dark {
  color-scheme: dark;

  --background: oklch(0.17 0.008 265);
  --foreground: oklch(0.95 0.004 265);
  --surface: oklch(0.2 0.009 265);
  --surface-raised: oklch(0.235 0.01 265);
  --border: oklch(0.28 0.012 265);
  --border-strong: oklch(0.36 0.014 265);
  --muted: oklch(0.24 0.01 265);
  --muted-foreground: oklch(0.68 0.014 265);

  --primary: oklch(0.68 0.17 265);
  --primary-foreground: oklch(0.16 0.01 265);
  --accent: oklch(0.75 0.13 195);
  --accent-foreground: oklch(0.16 0.01 265);

  --danger: oklch(0.65 0.19 25);
  --warning: oklch(0.78 0.15 75);
  --success: oklch(0.7 0.14 150);

  --ring: oklch(0.68 0.17 265);

  --diagram-background: var(--background);
  --diagram-node: oklch(0.26 0.018 265);
  --diagram-node-border: oklch(0.6 0.13 265);
  --diagram-line: oklch(0.66 0.02 265);
  --diagram-text: var(--foreground);
  --diagram-cluster: oklch(0.22 0.012 265);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-surface-raised: var(--surface-raised);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-danger: var(--danger);
  --color-warning: var(--warning);
  --color-success: var(--success);
  --color-ring: var(--ring);
}

@layer base {
  * {
    border-color: var(--border);
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }

  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

