import type { DiagramElement, RenderError } from '@mr/core'
import {
  type FrameToHost,
  PROTOCOL_VERSION,
  type RenderConfig,
  frameToHostSchema,
  sanitizeSvg,
} from '@mr/renderer'

/**
 * Host side of the render frame.
 *
 * Owns one reused iframe, one job in flight, and cancellation. The last good result is
 * kept here so a parse error can never clear the canvas.
 *
 * See docs/architecture/rendering.md.
 */

export interface RenderResult {
  svg: string
  viewBox: { x: number; y: number; width: number; height: number }
  elements: readonly DiagramElement[]
  coarse: boolean
  durationMs: number
}

export interface RenderHostEvents {
  onResult(result: RenderResult): void
  onError(error: RenderError): void
  onReady(mermaidVersion: string): void
}

const FRAME_SRC = '/render-frame.html'
const TIMEOUT_MS = 20_000

export class RenderHost {
  #frame: HTMLIFrameElement
  #ready = false
  #queue: (() => void)[] = []
  #currentJob: string | null = null
  #timer: ReturnType<typeof setTimeout> | null = null
  #seq = 0
  #events: RenderHostEvents

  constructor(events: RenderHostEvents) {
    this.#events = events

    const frame = document.createElement('iframe')
    frame.src = FRAME_SRC
    frame.title = 'diagram renderer'
    // No allow-same-origin: script smuggled through diagram text cannot reach this origin.
    frame.setAttribute('sandbox', 'allow-scripts')
    frame.setAttribute('aria-hidden', 'true')
    frame.style.cssText =
      'position:absolute;width:1600px;height:1200px;border:0;visibility:hidden;pointer-events:none;left:-99999px;top:0'
    document.body.appendChild(frame)
    this.#frame = frame

    window.addEventListener('message', this.#onMessage)
  }

  destroy(): void {
    window.removeEventListener('message', this.#onMessage)
    this.#clearTimer()
    this.#frame.remove()
  }

  /** Cancels whatever is in flight and starts a new job. */
  render(text: string, config: RenderConfig): void {
    if (this.#currentJob) this.#post({ type: 'cancel', jobId: this.#currentJob })

    const jobId = `j${++this.#seq}`
    this.#currentJob = jobId
    this.#clearTimer()
    this.#timer = setTimeout(() => {
      if (this.#currentJob !== jobId) return
      this.#currentJob = null
      this.#events.onError({
        kind: 'timeout',
        message: 'The diagram took too long to render and was stopped.',
      })
    }, TIMEOUT_MS)

    this.#post({ type: 'render', jobId, text, config })
  }

  #post(message: unknown): void {
    const send = () => this.#frame.contentWindow?.postMessage(message, '*')
    if (this.#ready) send()
    else this.#queue.push(send)
  }

  #clearTimer(): void {
    if (this.#timer !== null) {
      clearTimeout(this.#timer)
      this.#timer = null
    }
  }

  #onMessage = (event: MessageEvent<unknown>): void => {
    if (event.source !== this.#frame.contentWindow) return

    const parsed = frameToHostSchema.safeParse(event.data)
    if (!parsed.success) return

    const message: FrameToHost = parsed.data

    if (message.type === 'ready') {
      if (message.protocol !== PROTOCOL_VERSION) return
      if (this.#ready) return
      this.#ready = true
      for (const send of this.#queue) send()
      this.#queue = []
      this.#events.onReady(message.mermaidVersion)
      return
    }

    // A job the host already moved past. Discard it rather than let it reach the canvas.
    if (message.jobId !== this.#currentJob) return

    this.#clearTimer()
    this.#currentJob = null

    if (message.type === 'ok') {
      this.#events.onResult({
        svg: sanitizeSvg(message.svg),
        viewBox: message.viewBox,
        elements: message.elements,
        coarse: message.coarse,
        durationMs: message.durationMs,
      })
    } else if (message.type === 'error') {
      this.#events.onError(message.error)
    }
  }
}

