  #onMessage = (event: MessageEvent<unknown>): void => {
    if (event.source !== this.#frame.contentWindow) return

    const parsed = frameToHostSchema.safeParse(event.data)
    if (!parsed.success) return

    const message: FrameToHost = parsed.data

    if (message.type === 'ready') {
      if (message.protocol !== PROTOCOL_VERSION) return
      if (this.#ready) return
      this.#ready = true
      for (const send of this.#queue) send()
      this.#queue = []
      this.#events.onReady(message.mermaidVersion)
      return
    }

    // A job the host already moved past. Discard it rather than let it reach the canvas.
    if (message.jobId !== this.#currentJob) return

    this.#clearTimer()
    this.#currentJob = null

    if (message.type === 'ok') {
      this.#events.onResult({
        svg: sanitizeSvg(message.svg),
        viewBox: message.viewBox,
        elements: message.elements,
        coarse: message.coarse,
        durationMs: message.durationMs,
      })
    } else if (message.type === 'error') {
      this.#events.onError(message.error)
    }
  }
}

