import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { detectDiagramType, type RenderError } from '@mr/core'
import type { RenderConfig } from '@mr/renderer'
import { mermaidThemeVariables } from '@mr/ui'
import { CodeEditor } from '../components/code-editor'
import { DiagramCanvas } from '../components/diagram-canvas'
import { RenderHost, type RenderResult } from '../lib/render-host'

const STARTER = `flowchart TD
    A[Write Mermaid] --> B{Parses?}
    B -- yes --> C[Render in the frame]
    B -- no --> D[Keep the last good render]
    D --> A
    C --> E[Export SVG, PNG, PDF]
`

/** Small documents get a short debounce, large ones a longer one. */
function debounceFor(text: string): number {
  return text.length > 20_000 ? 500 : 180
}

export function EditorScreen() {
  const [text, setText] = useState(STARTER)
  // The last good render. Never cleared by an error — that is the whole point.
  const [result, setResult] = useState<RenderResult | null>(null)
  const [error, setError] = useState<RenderError | null>(null)
  const [pending, setPending] = useState(false)
  const [version, setVersion] = useState<string | null>(null)

  const hostRef = useRef<RenderHost | null>(null)

  useEffect(() => {
    const host = new RenderHost({
      onReady: (mermaidVersion) => setVersion(mermaidVersion),
      onResult: (next) => {
        setResult(next)
        setError(null)
        setPending(false)
      },
      onError: (next) => {
        setError(next)
        setPending(false)
      },
    })
    hostRef.current = host
    return () => {
      host.destroy()
      hostRef.current = null
    }
  }, [])

  const config = useMemo<RenderConfig>(
    () => ({
      securityLevel: 'strict',
      theme: 'base',
      themeVariables: mermaidThemeVariables(),
      fontFamily: getComputedStyle(document.documentElement).getPropertyValue('--font-sans').trim(),
      coarseThreshold: 400,
    }),
    [],
  )

  useEffect(() => {
    const host = hostRef.current
    if (!host) return
    setPending(true)
    const id = setTimeout(() => host.render(text, config), debounceFor(text))
    return () => clearTimeout(id)
  }, [text, config])

  const detected = useMemo(() => detectDiagramType(text), [text])
  const onChange = useCallback((next: string) => setText(next), [])

  return (
    <div className="flex h-screen flex-col bg-background text-foreground">
      <header className="flex h-11 shrink-0 items-center gap-3 border-b px-3 text-sm">
        <span className="font-medium">mermaid-render</span>
        <span className="text-muted-foreground">
          {detected ? detected.label : 'No diagram type detected'}
          {detected?.beta ? ' · experimental' : ''}
        </span>
        <span className="ml-auto tabular-nums text-muted-foreground text-xs">
          {version ? `mermaid ${version}` : 'starting renderer…'}
          {result ? ` · ${Math.round(result.durationMs)} ms · ${result.elements.length} elements` : ''}
        </span>
      </header>

      <main className="flex min-h-0 flex-1">
        <section className="flex min-w-0 flex-1 flex-col border-r">
          <CodeEditor value={text} onChange={onChange} />
        </section>
        <section className="relative flex min-w-0 flex-1 flex-col">
          <DiagramCanvas result={result} pending={pending} />
        </section>
      </main>

      <footer
        className="flex h-8 shrink-0 items-center gap-2 border-t px-3 text-xs"
        role="status"
        aria-live="polite"
      >
        {error ? (
          <>
            <span className="font-medium text-danger">Cannot render</span>
            <span className="truncate text-muted-foreground">{error.message}</span>
            <span className="ml-auto text-muted-foreground">Showing the last good render</span>
          </>
        ) : (
          <span className="text-muted-foreground">{pending ? 'Rendering…' : 'Up to date'}</span>
        )}
      </footer>
    </div>
  )
}

