import type { DiagramElement } from '@mr/core'
import {
  type FrameToHost,
  type HostToFrame,
  PROTOCOL_VERSION,
  hostToFrameSchema,
} from '@mr/renderer'
import mermaid from 'mermaid'

/**
 * Render frame entry point.
 *
 * The only place in the product that calls `mermaid.render`. It cannot be a Web Worker:
 * mermaid measures text with getBBox and getComputedTextLength, which need a real layout
 * engine. See adr/0003-render-frame-not-worker.md.
 */

const stage = document.getElementById('stage')
if (!stage) throw new Error('render frame is missing its stage element')

/** Jobs the host cancelled. Checked between phases, and again before answering. */
const cancelled = new Set<string>()

function post(message: FrameToHost): void {
  // The host is cross-document; '*' is required because a sandboxed frame without
  // allow-same-origin has an opaque origin. The host validates every message it receives.
  window.parent.postMessage(message, '*')
}

function describeError(error: unknown): { message: string; raw: string } {
  const raw = error instanceof Error ? error.message : String(error)
  return { message: raw, raw }
}

/** Reads geometry from the laid-out SVG. Only possible here, where layout exists. */
function collectElements(svg: SVGSVGElement): DiagramElement[] {
  const elements: DiagramElement[] = []
  for (const node of svg.querySelectorAll<SVGGraphicsElement>('[id]')) {
    const kind = node.getAttribute('class')?.split(/\s+/)[0]
    if (!kind) continue
    if (!['node', 'cluster', 'edgePath', 'edgeLabel', 'actor', 'task'].includes(kind)) continue
    let box: DOMRect
    try {
      box = node.getBBox()
    } catch {
      continue
    }
    elements.push({
      id: node.id,
      kind,
      box: { x: box.x, y: box.y, width: box.width, height: box.height },
    })
  }
  return elements
}

function readViewBox(svg: SVGSVGElement): { x: number; y: number; width: number; height: number } {
  const vb = svg.viewBox.baseVal
  if (vb && vb.width > 0) return { x: vb.x, y: vb.y, width: vb.width, height: vb.height }
  const box = svg.getBBox()
  return { x: box.x, y: box.y, width: box.width, height: box.height }
}

async function handleRender(message: Extract<HostToFrame, { type: 'render' }>): Promise<void> {
  const { jobId, text, config } = message
  const started = performance.now()

  mermaid.initialize({
    startOnLoad: false,
    securityLevel: config.securityLevel,
    theme: config.theme,
    themeVariables: config.themeVariables,
    fontFamily: config.fontFamily,
  })

  try {
    await mermaid.parse(text)
  } catch (error) {
    if (cancelled.has(jobId)) return
    const { message: msg, raw } = describeError(error)
    post({ type: 'error', jobId, error: { kind: 'parse', message: msg, raw } })
    return
  }

  if (cancelled.has(jobId)) return

  stage.innerHTML = ''
  const container = document.createElement('div')
  stage.appendChild(container)

  try {
    const { svg } = await mermaid.render(`d-${jobId}`, text, container)
    if (cancelled.has(jobId)) return

    container.innerHTML = svg
    const node = container.querySelector('svg')
    if (!node) throw new Error('mermaid produced no svg element')

    const elements = collectElements(node)
    post({
      type: 'ok',
      jobId,
      svg,
      viewBox: readViewBox(node),
      elements,
      coarse: elements.length > config.coarseThreshold,
      durationMs: performance.now() - started,
    })
  } catch (error) {
    if (cancelled.has(jobId)) return
    const { message: msg, raw } = describeError(error)
    post({ type: 'error', jobId, error: { kind: 'render', message: msg, raw } })
  } finally {
    stage.innerHTML = ''
    cancelled.delete(jobId)
  }
}

async function handleParse(message: Extract<HostToFrame, { type: 'parse' }>): Promise<void> {
  const { jobId, text } = message
  try {
    const result = await mermaid.parse(text)
    if (cancelled.has(jobId)) return
    post({ type: 'parsed', jobId, typeId: result === false ? null : (result.diagramType ?? null) })
  } catch (error) {
    if (cancelled.has(jobId)) return
    const { message: msg, raw } = describeError(error)
    post({ type: 'error', jobId, error: { kind: 'parse', message: msg, raw } })
  }
}

window.addEventListener('message', (event: MessageEvent<unknown>) => {
  const parsed = hostToFrameSchema.safeParse(event.data)
  if (!parsed.success) return

  const message = parsed.data
  switch (message.type) {
    case 'init':
      post({ type: 'ready', protocol: PROTOCOL_VERSION, mermaidVersion: '11.16.1' })
      break
    case 'cancel':
      cancelled.add(message.jobId)
      break
    case 'render':
      void handleRender(message)
      break
    case 'parse':
      void handleParse(message)
      break
  }
})

post({ type: 'ready', protocol: PROTOCOL_VERSION, mermaidVersion: '11.16.1' })

