import { StreamLanguage, type StreamParser } from '@codemirror/language'
import type { DialectData } from './data'

/**
 * One tokenizer, parameterised per dialect.
 *
 * The shared preamble — YAML frontmatter, `%%{init}%%` directives and line comments — is
 * handled identically for every diagram type, because it is identical in mermaid. Only
 * the keyword sets, operators and comment token vary, and those come from `data.ts`.
 *
 * A dialect is promoted to a Lezer grammar only when it needs a real syntax tree; see
 * docs/architecture/editor.md.
 */

export interface DialectState {
  /** Inside the leading `---` YAML block. */
  frontmatter: boolean
  /** Inside a `%%{ … }%%` directive that spans lines. */
  directive: boolean
  /** Quote character of the string currently open, or null. */
  string: string | null
  /** True until the first non-blank line has been tokenized. */
  first: boolean
}

const BRACKETS = '()[]{}'

function escapeForClass(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

export function makeStreamParser(data: DialectData): StreamParser<DialectState> {
  // Longest first, so `-->>` is never read as `-->` followed by `>`.
  const operators = [...data.operators].sort((a, b) => b.length - a.length)
  const statements = new Set(data.statements)
  const constants = new Set(data.constants)
  const commentRe = new RegExp(`^${escapeForClass(data.lineComment)}`)

  return {
    name: 'mermaid',

    startState(): DialectState {
      return { frontmatter: false, directive: false, string: null, first: true }
    },

    token(stream, state): string | null {
      // Unterminated string carried over from the previous line.
      if (state.string !== null) {
        const quote = state.string
        while (!stream.eol()) {
          if (stream.next() === quote) {
            state.string = null
            break
          }
        }
        return 'string'
      }

      if (state.directive) {
        if (stream.skipTo('}%%')) {
          stream.match('}%%')
          state.directive = false
        } else {
          stream.skipToEnd()
        }
        return 'meta'
      }

      if (state.frontmatter) {
        if (stream.sol() && stream.match(/^---\s*$/)) {
          state.frontmatter = false
          return 'meta'
        }
        stream.skipToEnd()
        return 'meta'
      }

      if (stream.sol()) {
        if (state.first && stream.match(/^---\s*$/)) {
          state.first = false
          state.frontmatter = true
          return 'meta'
        }
        if (stream.eatSpace()) return null
      }

      if (stream.eatSpace()) return null

      if (stream.match('%%{')) {
        state.directive = true
        return 'meta'
      }

      if (stream.match(commentRe, false)) {
        stream.skipToEnd()
        return 'comment'
      }

      const quote = stream.peek()
      if (quote === '"' || quote === "'" || quote === '`') {
        stream.next()
        state.string = quote
        while (!stream.eol()) {
          if (stream.next() === quote) {
            state.string = null
            break
          }
        }
        return 'string'
      }

      if (stream.match(/^[+-]?(\d+\.?\d*|\.\d+)(ms|[smhdwMy])?\b/)) {
        return 'number'
      }

      for (const operator of operators) {
        if (stream.match(operator)) return 'operator'
      }

      const next = stream.peek()
      if (next !== null && BRACKETS.includes(next)) {
        stream.next()
        return 'bracket'
      }

      const word = stream.match(/^[A-Za-z_][\w-]*/)
      if (word) {
        state.first = false
        const text = String(word[0])
        if (statements.has(text)) return 'keyword'
        if (constants.has(text)) return 'atom'
        return 'variableName'
      }

      stream.next()
      return null
    },

    languageData: {
      commentTokens: { line: data.lineComment },
      closeBrackets: { brackets: ['(', '[', '{', '"', "'"] },
      indentOnInput: data.blockClose ? new RegExp(`^\\s*${data.blockClose}$`) : undefined,
    },
  }
}

export function makeLanguage(data: DialectData) {
  return StreamLanguage.define(makeStreamParser(data))
}

