import type { StreamLanguage } from '@codemirror/language'
import { DIAGRAM_TYPES, type DiagramTypeId } from '@mr/core'
import { DIALECTS, type DialectData } from './data'
import { type DialectState, makeLanguage } from './stream'

/**
 * Dialect registry: one CodeMirror language mode per diagram type.
 *
 * Keywords are not written here by hand. They come from `data.ts`, which is derived from
 * `docs/knowledge/diagrams/<id>.md`, which is derived from `mermaid-upstream/`. If a
 * dialect and the catalog disagree, the catalog is fixed first.
 */

export interface Dialect {
  readonly id: DiagramTypeId
  readonly data: DialectData
  readonly language: StreamLanguage<DialectState>
}

const cache = new Map<string, Dialect>()

export function getDialect(id: string): Dialect | undefined {
  const cached = cache.get(id)
  if (cached) return cached

  const data = (DIALECTS as Record<string, DialectData | undefined>)[id]
  if (!data) return undefined

  const dialect: Dialect = { id: id as DiagramTypeId, data, language: makeLanguage(data) }
  cache.set(id, dialect)
  return dialect
}

export function registeredDialectIds(): readonly string[] {
  return Object.keys(DIALECTS)
}

/** Types in the catalog that have no dialect. Asserted empty by a test. */
export function missingDialectIds(): readonly string[] {
  return DIAGRAM_TYPES.filter((t) => !(t.id in DIALECTS)).map((t) => t.id)
}

/** The canonical starter snippet for a type. */
export function starterFor(id: string): string | undefined {
  return (DIALECTS as Record<string, DialectData | undefined>)[id]?.starter
}

