import type { CompletionContext, CompletionResult, Completion } from '@codemirror/autocomplete'
import { DIAGRAM_TYPES } from '@mr/core'
import { getDialect } from './dialects/registry'

/**
 * Context-aware completion.
 *
 * Not a flat keyword dump: what is offered depends on where the cursor is. See
 * docs/architecture/editor.md.
 */

const IDENTIFIER = /[\w-]+$/

/** Identifiers already present in the document, most recent first. */
function documentIdentifiers(text: string, exclude: ReadonlySet<string>): string[] {
  const seen = new Set<string>()
  for (const match of text.matchAll(/\b[A-Za-z_][\w-]*\b/g)) {
    const word = match[0]
    if (!exclude.has(word)) seen.add(word)
  }
  return [...seen]
}

/** The diagram-type picker, offered only in an empty document. */
function diagramTypeCompletions(): Completion[] {
  return DIAGRAM_TYPES.filter((type) => type.doc !== null && type.id !== 'info').map((type) => ({
    label: type.keyword,
    type: 'class',
    detail: type.label + (type.beta ? ' · experimental' : ''),
    info: type.minVersion ? `Requires mermaid ${type.minVersion}+` : undefined,
    boost: type.beta ? -1 : 0,
  }))
}

export function mermaidCompletion(typeId: string | null) {
  return (context: CompletionContext): CompletionResult | null => {
    const word = context.matchBefore(IDENTIFIER)
    if (!word && !context.explicit) return null
    const from = word ? word.from : context.pos

    const before = context.state.doc.sliceString(0, context.pos)
    const isEmptyDocument = before.trim().length === word?.text.length || before.trim() === ''

    if (isEmptyDocument || typeId === null) {
      return { from, options: diagramTypeCompletions(), validFor: IDENTIFIER }
    }

    const dialect = getDialect(typeId)
    if (!dialect) return null

    const line = context.state.doc.lineAt(context.pos)
