      expect(starter).toBeDefined()
      expect(detectDiagramType(starter as string)?.id).toBe(type.id)
    })
  }

  test('starters are more than a two-node stub', () => {
    // `info` renders the mermaid version and has no body by design.
    const thin = DIAGRAM_TYPES.filter((t) => t.id !== 'info').filter(
      (t) => (starterFor(t.id) ?? '').trim().split('\n').length < 4,
    )
    expect(thin.map((t) => t.id)).toEqual([])
  })
})

describe('operator ordering', () => {
  // If a shorter operator is matched first, `-->>` becomes `-->` plus `>`.
  for (const [id, data] of Object.entries(DIALECTS)) {
    test(`${id} operators tokenize longest-first`, () => {
      const sorted = [...data.operators].sort((a, b) => b.length - a.length)
      for (let i = 0; i < sorted.length; i++) {
        for (let j = i + 1; j < sorted.length; j++) {
          const long = sorted[i] as string
          const short = sorted[j] as string
          if (long.startsWith(short)) expect(long.length).toBeGreaterThanOrEqual(short.length)
        }
      }
    })
  }
})

/** Runs the tokenizer over a source and returns the token names produced. */
function tokenize(id: string, source: string): string[] {
  const dialect = getDialect(id)
  if (!dialect) throw new Error(`no dialect for ${id}`)
  const parser = makeStreamParser(dialect.data)
  const state = parser.startState?.(2) ?? ({} as never)
  const tokens: string[] = []

  for (const line of source.split('\n')) {
    let pos = 0
    const stream = {
      pos: 0,
      start: 0,
      string: line,
      sol: () => stream.pos === 0,
      eol: () => stream.pos >= line.length,
      peek: () => (stream.pos < line.length ? (line[stream.pos] as string) : null),
      next: () => (stream.pos < line.length ? (line[stream.pos++] as string) : undefined),
      eatSpace: () => {
        const from = stream.pos
        while (stream.pos < line.length && /\s/.test(line[stream.pos] as string)) stream.pos++
        return stream.pos > from
      },
      skipToEnd: () => {
        stream.pos = line.length
      },
      skipTo: (text: string) => {
        const found = line.indexOf(text, stream.pos)
        if (found === -1) return false
        stream.pos = found
        return true
      },
      match: (pattern: string | RegExp, consume = true) => {
        if (typeof pattern === 'string') {
          if (line.startsWith(pattern, stream.pos)) {
            if (consume) stream.pos += pattern.length
            return true
          }
          return false
        }
        const result = pattern.exec(line.slice(stream.pos))
        if (result && result.index === 0) {
          if (consume) stream.pos += result[0].length
          return result
        }
        return null
      },
    } as never

    while (pos < line.length) {
      ;(stream as { start: number }).start = pos
      const token = parser.token(stream as never, state)
      const after = (stream as { pos: number }).pos
      if (after === pos) break
      if (token) tokens.push(token)
      pos = after
    }
  }
  return tokens
}

describe('tokenizer', () => {
  test('highlights the flowchart header as a keyword', () => {
    expect(tokenize('flowchart', 'flowchart TD')).toContain('keyword')
  })

  test('treats YAML frontmatter as meta', () => {
    const tokens = tokenize('flowchart', '---\ntitle: Hello\n---\nflowchart TD')
    expect(tokens.filter((t) => t === 'meta').length).toBeGreaterThan(0)
    expect(tokens).toContain('keyword')
  })

  test('treats an init directive as meta', () => {
    expect(tokenize('flowchart', "%%{init: {'theme':'dark'}}%%")).toContain('meta')
  })

  test('uses %% for comments in flowchart', () => {
    expect(tokenize('flowchart', '%% a note')).toEqual(['comment'])
  })

  test('uses // for comments in zenuml, not %%', () => {
    expect(tokenize('zenuml', '// a note')).toEqual(['comment'])
  })

  test('recognizes quoted strings', () => {
    expect(tokenize('pie', '"Dogs" : 386')).toEqual(['string', 'operator', 'number'])
  })

  test('recognizes gantt duration suffixes as numbers', () => {
    expect(tokenize('gantt', '12d')).toEqual(['number'])
    expect(tokenize('gantt', '500ms')).toEqual(['number'])
  })
})

