/**
 * SVG serialization.
 *
 * The SVG that comes out of the render frame is already sanitized, but it is not yet a
 * standalone file: it carries no XML namespace declaration, no explicit size, and its
 * colors come from CSS variables that only exist inside our application. An exported file
 * has to open correctly in Inkscape, Figma and a browser with none of that context.
 */

export interface SerializeOptions {
  /** Solid background, or false for transparent. */
  background?: string | false
  /** Resolve CSS custom properties to literal values. Required for standalone files. */
  inlineVariables?: boolean
}

const SVG_NS = 'http://www.w3.org/2000/svg'
const XLINK_NS = 'http://www.w3.org/1999/xlink'

function parseSvg(svg: string): SVGSVGElement {
  const doc = new DOMParser().parseFromString(svg, 'image/svg+xml')
  const root = doc.documentElement
  if (root.nodeName === 'parsererror' || root.namespaceURI !== SVG_NS) {
    throw new Error('Export failed: the diagram is not valid SVG.')
  }
  return root as unknown as SVGSVGElement
}

/**
 * Replaces `var(--token)` references with the value the token currently resolves to.
 *
 * Without this the exported file renders black-on-black outside the app, because the
 * custom properties are declared on our `:root` and travel nowhere.
 */
function inlineCustomProperties(root: SVGSVGElement, scope: Element): void {
  const computed = getComputedStyle(scope)
  const resolve = (value: string): string =>
    value.replace(/var\(\s*(--[\w-]+)\s*(?:,\s*([^)]*))?\)/g, (_, name: string, fallback = '') => {
      const resolved = computed.getPropertyValue(name).trim()
      return resolved !== '' ? resolved : fallback.trim()
    })

  for (const element of [root, ...root.querySelectorAll('*')]) {
    const style = element.getAttribute('style')
    if (style?.includes('var(')) element.setAttribute('style', resolve(style))
    for (const attribute of ['fill', 'stroke', 'color', 'stop-color']) {
      const value = element.getAttribute(attribute)
      if (value?.includes('var(')) element.setAttribute(attribute, resolve(value))
    }
  }

  for (const style of root.querySelectorAll('style')) {
    if (style.textContent?.includes('var(')) style.textContent = resolve(style.textContent)
  }
}

export interface SizedSvg {
  markup: string
  width: number
  height: number
}

/** Produces a standalone SVG string plus the intrinsic size callers need for rasterizing. */
export function serializeSvg(
  svg: string,
  viewBox: { x: number; y: number; width: number; height: number },
  options: SerializeOptions = {},
): SizedSvg {
  const root = parseSvg(svg)

  root.setAttribute('xmlns', SVG_NS)
  root.setAttribute('xmlns:xlink', XLINK_NS)

  const width = viewBox.width > 0 ? viewBox.width : Number(root.getAttribute('width')) || 0
  const height = viewBox.height > 0 ? viewBox.height : Number(root.getAttribute('height')) || 0
  if (width <= 0 || height <= 0) {
    throw new Error('Export failed: the diagram has no measurable size.')
  }

  root.setAttribute('width', String(width))
  root.setAttribute('height', String(height))
  root.setAttribute('viewBox', `${viewBox.x} ${viewBox.y} ${width} ${height}`)
  root.style.removeProperty('max-width')

  if (options.inlineVariables !== false && typeof document !== 'undefined') {
    inlineCustomProperties(root, document.documentElement)
  }

  if (options.background) {
    const rect = root.ownerDocument.createElementNS(SVG_NS, 'rect')
    rect.setAttribute('x', String(viewBox.x))
    rect.setAttribute('y', String(viewBox.y))
    rect.setAttribute('width', String(width))
    rect.setAttribute('height', String(height))
    rect.setAttribute('fill', options.background)
    root.insertBefore(rect, root.firstChild)
  }

  const markup = new XMLSerializer().serializeToString(root)
  return { markup: `<?xml version="1.0" encoding="UTF-8"?>\n${markup}`, width, height }
}

