import type { SizedSvg } from './svg'

/**
 * Raster export.
 *
 * This runs on the main thread, not in a Web Worker. Rasterizing an SVG requires the
 * browser's image decoder, reached through `HTMLImageElement`; `createImageBitmap` accepts
 * SVG blobs inconsistently across browsers and not at all in Firefox. So the honest
 * position is: rasterization is a main-thread operation, kept brief by doing it once per
 * export rather than per frame.
 */

export type RasterFormat = 'png' | 'webp'

const MIME: Record<RasterFormat, string> = {
  png: 'image/png',
  webp: 'image/webp',
}

/** Browsers refuse canvases beyond roughly this area; Safari is the tightest. */
const MAX_CANVAS_AREA = 268_435_456

export interface RasterOptions {
  format: RasterFormat
  scale: number
  background?: string | false
  quality?: number
}

function loadImage(markup: string): Promise<HTMLImageElement> {
  const blob = new Blob([markup], { type: 'image/svg+xml;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  return new Promise((resolve, reject) => {
    const image = new Image()
    image.decoding = 'sync'
    image.onload = () => {
      URL.revokeObjectURL(url)
      resolve(image)
    }
    image.onerror = () => {
      URL.revokeObjectURL(url)
      reject(new Error('Export failed: the diagram could not be rasterized.'))
    }
    image.src = url
  })
}

/** Clamps the scale so the canvas stays within what browsers will allocate. */
export function clampScale(width: number, height: number, scale: number): number {
  const area = width * height * scale * scale
  if (area <= MAX_CANVAS_AREA) return scale
  return Math.max(1, Math.sqrt(MAX_CANVAS_AREA / (width * height)))
}

export async function rasterize(svg: SizedSvg, options: RasterOptions): Promise<Blob> {
  const scale = clampScale(svg.width, svg.height, options.scale)
  const width = Math.max(1, Math.round(svg.width * scale))
  const height = Math.max(1, Math.round(svg.height * scale))

  const image = await loadImage(svg.markup)
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height

  const context = canvas.getContext('2d')
  if (!context) throw new Error('Export failed: no 2D canvas context is available.')

  if (options.background) {
    context.fillStyle = options.background
    context.fillRect(0, 0, width, height)
  }
  context.drawImage(image, 0, 0, width, height)

  const blob = await new Promise<Blob | null>((resolve) =>
    canvas.toBlob(resolve, MIME[options.format], options.quality),
  )
  if (!blob) throw new Error('Export failed: the image could not be encoded.')
  return blob
}

