/**
 * Client-side export. No server round trip, ever.
 *
 * - SVG: the sanitized string, with fonts and styles inlined so it opens correctly
 *   outside this application.
 * - PNG / WEBP: rasterized through OffscreenCanvas in a real Web Worker. That step is
 *   genuinely DOM-free, which is why it may live in a worker while rendering may not.
 * - PDF: vector, via svg2pdf. Never a rasterized image pasted into a page.
 */

export type ExportFormat = 'svg' | 'png' | 'webp' | 'pdf'

export interface ExportOptions {
  format: ExportFormat
  /** Raster scale factor. Ignored for svg and pdf. */
  scale?: number
  /** Transparent background when false. */
  background?: string | false
  fileName?: string
}

export const DEFAULT_EXPORT_OPTIONS = {
  format: 'svg',
  scale: 2,
  background: false,
} as const satisfies ExportOptions

