import { describe, expect, test } from 'bun:test'
import { EXPORT_EXTENSIONS, exportFileName, rasterDimensions } from './index'
import { clampScale } from './raster'

describe('exportFileName', () => {
  test('slugifies a diagram name', () => {
    expect(exportFileName('My Order Flow', 'svg')).toBe('My-Order-Flow.svg')
  })

  test('strips characters that break file systems', () => {
    expect(exportFileName('a/b:c*d?', 'png')).toBe('abcd.png')
  })

  test('falls back when the name has nothing usable', () => {
    expect(exportFileName('///', 'pdf')).toBe('diagram.pdf')
    expect(exportFileName('   ', 'webp')).toBe('diagram.webp')
  })

  test('uses the right extension for every format', () => {
    for (const [format, extension] of Object.entries(EXPORT_EXTENSIONS)) {
      expect(exportFileName('x', format as never).endsWith(`.${extension}`)).toBe(true)
    }
  })
})

describe('clampScale', () => {
  test('leaves a normal diagram alone', () => {
    expect(clampScale(800, 600, 2)).toBe(2)
  })

  test('clamps a scale that would exceed the canvas limit', () => {
    // 8000 x 6000 at 4x is 768 megapixels; browsers refuse it.
    expect(clampScale(8000, 6000, 4)).toBeLessThan(4)
  })

  test('never clamps below 1', () => {
    expect(clampScale(40000, 40000, 8)).toBeGreaterThanOrEqual(1)
  })
})

describe('rasterDimensions', () => {
  test('reports the size the user will actually get', () => {
    expect(rasterDimensions({ width: 400, height: 300 }, 2)).toEqual({
      width: 800,
      height: 600,
      clamped: false,
    })
  })

  test('flags when the requested scale was reduced', () => {
    expect(rasterDimensions({ width: 8000, height: 6000 }, 4).clamped).toBe(true)
  })
})

