import {
  CURRENT_SCHEMA_VERSION,
  type DiagramDocument,
  type Folder,
  type Revision,
  detectDiagramType,
  documentSchema,
  folderSchema,
  revisionSchema,
} from '@mr/core'
import { type IDBPDatabase, openDB } from 'idb'
import { runMigrations } from './migrations'
import {
  type BlobStore,
  type DocumentRepository,
  type FolderRepository,
  type ListDocumentsQuery,
  type Page,
  type PreferenceStore,
  QuotaExceededError,
  type RevisionRepository,
  type StorageQuota,
  type Workspace,
} from './ports'
import { DB_NAME, DB_VERSION, type WorkspaceSchema } from './schema'

/**
 * The IndexedDB/OPFS adapter — the only module in the repository that imports a browser
 * storage API. Everything above it depends on the ports in `ports.ts`, so the phase-2
 * server can implement the same contract without changing a line of consumer code.
 */

/** UUID v7: sorts by creation time, so listing needs no secondary index. */
export function uuidv7(now: number, random: () => number = Math.random): string {
  const timeHex = now.toString(16).padStart(12, '0')
  const bytes = new Uint8Array(10)
  for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(random() * 256)
  // Version 7 and the RFC 4122 variant bits.
  bytes[0] = ((bytes[0] as number) & 0x0f) | 0x70
  bytes[2] = ((bytes[2] as number) & 0x3f) | 0x80
  const rest = [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('')
  return [
    timeHex.slice(0, 8),
    timeHex.slice(8, 12),
    rest.slice(0, 4),
    rest.slice(4, 8),
    rest.slice(8, 20),
  ].join('-')
}

function isQuotaError(error: unknown): boolean {
  return (
    error instanceof DOMException &&
    (error.name === 'QuotaExceededError' || error.name === 'NS_ERROR_DOM_QUOTA_REACHED')
  )
}

export async function openWorkspaceDb(): Promise<IDBPDatabase<WorkspaceSchema>> {
  return openDB<WorkspaceSchema>(DB_NAME, DB_VERSION, {
    upgrade(db, oldVersion, newVersion, tx) {
      runMigrations(db, tx, oldVersion, newVersion ?? DB_VERSION)
    },
  })
}

export async function createIndexedDbWorkspace(now = () => Date.now()): Promise<Workspace> {
  const db = await openWorkspaceDb()

  async function guard<T>(operation: () => Promise<T>): Promise<T> {
    try {
      return await operation()
    } catch (error) {
      if (isQuotaError(error)) throw new QuotaExceededError(await quota())
      throw error
    }
  }

  async function quota(): Promise<StorageQuota> {
    const estimate = await navigator.storage?.estimate?.().catch(() => undefined)
    return {
      usage: estimate?.usage ?? 0,
      quota: estimate?.quota ?? 0,
      persisted: (await navigator.storage?.persisted?.().catch(() => false)) ?? false,
    }
  }

  const documents: DocumentRepository = {
    async list(query: ListDocumentsQuery = {}): Promise<Page<DiagramDocument>> {
      const all = await db.getAllFromIndex('documents', 'by-updated')
      const search = query.search?.trim().toLowerCase()

      const items = all
        .reverse()
        .filter((doc) => (query.includeDeleted ? true : doc.deletedAt === null))
        .filter((doc) => query.folderId === undefined || doc.folderId === query.folderId)
        .filter((doc) => query.typeId === undefined || doc.typeId === query.typeId)
        .filter(
          (doc) =>
            !search ||
            doc.name.toLowerCase().includes(search) ||
            doc.body.toLowerCase().includes(search),
        )

      const limit = query.limit ?? items.length
      return { items: items.slice(0, limit), nextCursor: null }
    },

    async get(id) {
      return db.get('documents', id)
    },

    async create(input) {
      const timestamp = now()
      const document = documentSchema.parse({
        id: input.id ?? uuidv7(timestamp),
        name: input.name,
        typeId: detectDiagramType(input.body)?.id ?? null,
        body: input.body,
        folderId: input.folderId ?? null,
        tags: input.tags ?? [],
        createdAt: timestamp,
        updatedAt: timestamp,
        deletedAt: null,
        schemaVersion: CURRENT_SCHEMA_VERSION,
      })
      await guard(() => db.put('documents', document))
      return document
    },

    async update(id, patch) {
      const existing = await db.get('documents', id)
      if (!existing) throw new Error(`No diagram with id ${id}`)
      const body = patch.body ?? existing.body
      const next = documentSchema.parse({
        ...existing,
        ...patch,
        id: existing.id,
        body,
        // Always re-derived: `body` is authoritative, the cached type is not.
        typeId: detectDiagramType(body)?.id ?? null,
        updatedAt: now(),
      })
      await guard(() => db.put('documents', next))
      return next
    },

    async delete(id) {
      const existing = await db.get('documents', id)
      if (!existing) return
      await guard(() => db.put('documents', { ...existing, deletedAt: now() }))
    },

    async restore(id) {
      const existing = await db.get('documents', id)
      if (!existing) throw new Error(`No diagram with id ${id}`)
      const next = { ...existing, deletedAt: null, updatedAt: now() }
      await guard(() => db.put('documents', next))
      return next
    },

    async purge(id) {
      const tx = db.transaction(['documents', 'revisions'], 'readwrite')
      await tx.objectStore('documents').delete(id)
      const index = tx.objectStore('revisions').index('by-document')
      for await (const cursor of index.iterate(id)) await cursor.delete()
      await tx.done
    },
  }

  const revisions: RevisionRepository = {
    async append(documentId, body, label) {
      const existing = await db.getAllFromIndex('revisions', 'by-document', documentId)
      const revision = revisionSchema.parse({
        documentId,
        seq: existing.length,
        body,
        label: label ?? null,
        createdAt: now(),
      })
      await guard(() => db.put('revisions', revision))
      return revision
    },
    async list(documentId) {
      const all = await db.getAllFromIndex('revisions', 'by-document', documentId)
      return all.sort((a, b) => b.seq - a.seq)
    },
    async get(documentId, seq) {
      return db.get('revisions', [documentId, seq])
    },
    async prune(documentId, keep) {
      const all = (await db.getAllFromIndex('revisions', 'by-document', documentId)).sort(
        (a: Revision, b: Revision) => b.seq - a.seq,
      )
      const tx = db.transaction('revisions', 'readwrite')
      for (const revision of all.slice(keep)) {
        await tx.store.delete([revision.documentId, revision.seq])
      }
      await tx.done
    },
  }

  const folders: FolderRepository = {
    async list() {
      const all = await db.getAll('folders')
      return all.sort((a: Folder, b: Folder) => a.position - b.position)
    },
    async create(input) {
      const folder = folderSchema.parse({ ...input, id: uuidv7(now()) })
      await guard(() => db.put('folders', folder))
      return folder
    },
    async update(id, patch) {
      const existing = await db.get('folders', id)
      if (!existing) throw new Error(`No folder with id ${id}`)
      const next = folderSchema.parse({ ...existing, ...patch, id: existing.id })
      await guard(() => db.put('folders', next))
      return next
    },
    async delete(id) {
      await db.delete('folders', id)
    },
  }

  const blobs: BlobStore = {
    async put(id, blob) {
      await guard(() => db.put('blobs', { id, blob, size: blob.size, type: blob.type }))
    },
    async get(id) {
      return (await db.get('blobs', id))?.blob
    },
    async delete(id) {
      await db.delete('blobs', id)
    },
    async size(id) {
      return (await db.get('blobs', id))?.size ?? 0
    },
  }

  const preferences: PreferenceStore = {
    async get<T>(key: string) {
      return (await db.get('preferences', key))?.value as T | undefined
    },
    async set<T>(key: string, value: T) {
      await guard(() => db.put('preferences', { key, value }))
    },
  }

  return {
    documents,
    revisions,
    folders,
    blobs,
    preferences,
    quota,
    async requestPersistence() {
      return (await navigator.storage?.persist?.().catch(() => false)) ?? false
    },
  }
}

