    async delete(id) {
      const existing = await db.get('documents', id)
      if (!existing) return
      await guard(() => db.put('documents', { ...existing, deletedAt: now() }))
    },

    async restore(id) {
      const existing = await db.get('documents', id)
      if (!existing) throw new Error(`No diagram with id ${id}`)
      const next = { ...existing, deletedAt: null, updatedAt: now() }
      await guard(() => db.put('documents', next))
      return next
    },

    async purge(id) {
      const tx = db.transaction(['documents', 'revisions'], 'readwrite')
      await tx.objectStore('documents').delete(id)
      const index = tx.objectStore('revisions').index('by-document')
      for await (const cursor of index.iterate(id)) await cursor.delete()
      await tx.done
    },
  }

  const revisions: RevisionRepository = {
    async append(documentId, body, label) {
      const existing = await db.getAllFromIndex('revisions', 'by-document', documentId)
      const revision = revisionSchema.parse({
        documentId,
        seq: existing.length,
        body,
        label: label ?? null,
        createdAt: now(),
      })
      await guard(() => db.put('revisions', revision))
      return revision
    },
    async list(documentId) {
      const all = await db.getAllFromIndex('revisions', 'by-document', documentId)
      return all.sort((a, b) => b.seq - a.seq)
    },
    async get(documentId, seq) {
      return db.get('revisions', [documentId, seq])
    },
    async prune(documentId, keep) {
      const all = (await db.getAllFromIndex('revisions', 'by-document', documentId)).sort(
        (a: Revision, b: Revision) => b.seq - a.seq,
      )
      const tx = db.transaction('revisions', 'readwrite')
      for (const revision of all.slice(keep)) {
        await tx.store.delete([revision.documentId, revision.seq])
      }
      await tx.done
    },
  }

  const folders: FolderRepository = {
    async list() {
      const all = await db.getAll('folders')
      return all.sort((a: Folder, b: Folder) => a.position - b.position)
    },
    async create(input) {
      const folder = folderSchema.parse({ ...input, id: uuidv7(now()) })
      await guard(() => db.put('folders', folder))
      return folder
    },
    async update(id, patch) {
      const existing = await db.get('folders', id)
      if (!existing) throw new Error(`No folder with id ${id}`)
      const next = folderSchema.parse({ ...existing, ...patch, id: existing.id })
      await guard(() => db.put('folders', next))
      return next
    },
    async delete(id) {
      await db.delete('folders', id)
    },
  }

  const blobs: BlobStore = {
    async put(id, blob) {
      await guard(() => db.put('blobs', { id, blob, size: blob.size, type: blob.type }))
    },
    async get(id) {
      return (await db.get('blobs', id))?.blob
    },
    async delete(id) {
      await db.delete('blobs', id)
    },
    async size(id) {
      return (await db.get('blobs', id))?.size ?? 0
    },
  }

  const preferences: PreferenceStore = {
    async get<T>(key: string) {
      return (await db.get('preferences', key))?.value as T | undefined
    },
    async set<T>(key: string, value: T) {
      await guard(() => db.put('preferences', { key, value }))
    },
  }

  return {
    documents,
    revisions,
    folders,
    blobs,
    preferences,
    quota,
    async requestPersistence() {
      return (await navigator.storage?.persist?.().catch(() => false)) ?? false
    },
  }
}

