import { describe, expect, test } from 'bun:test'
import { MIGRATIONS } from './migrations'
import { uuidv7 } from './indexeddb'
import { DB_VERSION } from './schema'

describe('migrations', () => {
  test('versions are unique and contiguous from 1', () => {
    const versions = MIGRATIONS.map((m) => m.version)
    expect(versions).toEqual(versions.map((_, index) => index + 1))
  })

  test('the database version matches the highest migration', () => {
    const highest = Math.max(...MIGRATIONS.map((m) => m.version))
    expect(DB_VERSION).toBe(highest)
  })

  test('every migration describes what it does', () => {
    for (const migration of MIGRATIONS) {
      expect(migration.description.length).toBeGreaterThan(10)
    }
  })
})

describe('uuidv7', () => {
  const deterministic = () => 0.5

  test('has the shape of a UUID', () => {
    expect(uuidv7(1_755_000_000_000, deterministic)).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )
  })

  test('sets the version 7 nibble', () => {
    expect(uuidv7(1_755_000_000_000, deterministic)[14]).toBe('7')
  })

  test('sets the RFC 4122 variant', () => {
    const variant = uuidv7(1_755_000_000_000, deterministic)[19] as string
    expect(['8', '9', 'a', 'b']).toContain(variant)
  })

  test('sorts lexicographically by creation time', () => {
    const earlier = uuidv7(1_755_000_000_000, deterministic)
    const later = uuidv7(1_755_000_001_000, deterministic)
    expect(earlier < later).toBe(true)
  })

  test('is unique across calls with real randomness', () => {
    const ids = new Set(Array.from({ length: 500 }, () => uuidv7(1_755_000_000_000)))
    expect(ids.size).toBe(500)
  })
})

