/**
 * A minimal StringStream stand-in.
 *
 * CodeMirror's own StringStream needs an EditorState to construct, which would drag a DOM
 * into `bun test`. The tokenizer only uses this surface, so implementing it directly keeps
 * the dialect tests headless and fast.
 */
class TestStream {
  pos = 0
  start = 0
  constructor(readonly string: string) {}

  sol(): boolean {
    return this.pos === 0
  }
  eol(): boolean {
    return this.pos >= this.string.length
  }
  peek(): string | null {
    return this.pos < this.string.length ? (this.string[this.pos] as string) : null
  }
  next(): string | undefined {
    return this.pos < this.string.length ? (this.string[this.pos++] as string) : undefined
  }
  eatSpace(): boolean {
    const from = this.pos
    while (this.pos < this.string.length && /\s/.test(this.string[this.pos] as string)) this.pos++
    return this.pos > from
  }
  skipToEnd(): void {
    this.pos = this.string.length
  }
  skipTo(text: string): boolean {
    const found = this.string.indexOf(text, this.pos)
    if (found === -1) return false
    this.pos = found
    return true
  }
  match(pattern: string | RegExp, consume = true): boolean | RegExpMatchArray | null {
    if (typeof pattern === 'string') {
      if (!this.string.startsWith(pattern, this.pos)) return false
      if (consume) this.pos += pattern.length
      return true
    }
    const result = pattern.exec(this.string.slice(this.pos))
    if (!result || result.index !== 0) return null
    if (consume) this.pos += result[0].length
    return result
  }
}

/** Runs the tokenizer over a source and returns the token names produced. */
function tokenize(id: string, source: string): string[] {
  const dialect = getDialect(id)
  if (!dialect) throw new Error(`no dialect for ${id}`)
  const parser = makeStreamParser(dialect.data)
  const state = parser.startState?.(2) as DialectState
  const tokens: string[] = []

  for (const line of source.split('\n')) {
