    while (stream.pos < line.length) {
      stream.start = stream.pos
      const before = stream.pos
      const token = parser.token(stream as unknown as StringStream, state)
      if (stream.pos === before) break
      if (token) tokens.push(token)
    }
  }
  return tokens
}

