      match: (pattern: string | RegExp, consume = true) => {
        if (typeof pattern === 'string') {
          if (line.startsWith(pattern, stream.pos)) {
            if (consume) stream.pos += pattern.length
            return true
          }
          return false
        }
        const result = pattern.exec(line.slice(stream.pos))
        if (result && result.index === 0) {
          if (consume) stream.pos += result[0].length
          return result
        }
        return null
      },
    } as never

    while (pos < line.length) {
      ;(stream as { start: number }).start = pos
      const token = parser.token(stream as never, state)
      const after = (stream as { pos: number }).pos
      if (after === pos) break
      if (token) tokens.push(token)
      pos = after
    }
  }
  return tokens
}

describe('tokenizer', () => {
  test('highlights the flowchart header as a keyword', () => {
    expect(tokenize('flowchart', 'flowchart TD')).toContain('keyword')
  })

  test('treats YAML frontmatter as meta', () => {
    const tokens = tokenize('flowchart', '---\ntitle: Hello\n---\nflowchart TD')
    expect(tokens.filter((t) => t === 'meta').length).toBeGreaterThan(0)
    expect(tokens).toContain('keyword')
  })

  test('treats an init directive as meta', () => {
    expect(tokenize('flowchart', "%%{init: {'theme':'dark'}}%%")).toContain('meta')
  })

  test('uses %% for comments in flowchart', () => {
    expect(tokenize('flowchart', '%% a note')).toEqual(['comment'])
  })

  test('uses // for comments in zenuml, not %%', () => {
    expect(tokenize('zenuml', '// a note')).toEqual(['comment'])
  })

  test('recognizes quoted strings', () => {
    expect(tokenize('pie', '"Dogs" : 386')).toEqual(['string', 'punctuation', 'number'])
  })

  test('recognizes gantt duration suffixes as numbers', () => {
    expect(tokenize('gantt', '12d')).toEqual(['number'])
    expect(tokenize('gantt', '500ms')).toEqual(['number'])
  })
})

import { describe, expect, test } from 'bun:test'
import { DIAGRAM_TYPES, detectDiagramType } from '@mr/core'
import { DIALECTS } from './data'
import { getDialect, missingDialectIds, starterFor } from './registry'
import { makeStreamParser } from './stream'

describe('dialect coverage', () => {
  // The load-bearing test: adding a type to the catalog without a dialect fails the build.
  test('every diagram type in the registry has a dialect', () => {
    expect(missingDialectIds()).toEqual([])
  })

  test('no dialect exists for a type outside the registry', () => {
    const known = new Set(DIAGRAM_TYPES.map((t) => t.id))
    expect(Object.keys(DIALECTS).filter((id) => !known.has(id as never))).toEqual([])
  })
})

describe('starters', () => {
  for (const type of DIAGRAM_TYPES) {
    test(`${type.id} starter is detected as its own type`, () => {
      const starter = starterFor(type.id)
      expect(starter).toBeDefined()
      expect(detectDiagramType(starter as string)?.id).toBe(type.id)
    })
  }

  test('starters are more than a two-node stub', () => {
    // `info` renders the mermaid version and has no body by design.
    const thin = DIAGRAM_TYPES.filter((t) => t.id !== 'info').filter(
      (t) => (starterFor(t.id) ?? '').trim().split('\n').length < 4,
    )
    expect(thin.map((t) => t.id)).toEqual([])
  })
})

describe('operator ordering', () => {
  // If a shorter operator is matched first, `-->>` becomes `-->` plus `>`.
  for (const [id, data] of Object.entries(DIALECTS)) {
    test(`${id} operators tokenize longest-first`, () => {
      const sorted = [...data.operators].sort((a, b) => b.length - a.length)
      for (let i = 0; i < sorted.length; i++) {
        for (let j = i + 1; j < sorted.length; j++) {
          const long = sorted[i] as string
          const short = sorted[j] as string
          if (long.startsWith(short)) expect(long.length).toBeGreaterThanOrEqual(short.length)
        }
      }
    })
  }
})

/**
 * A minimal StringStream stand-in.
 *
 * CodeMirror's own StringStream needs an EditorState to construct, which would drag a DOM
 * into `bun test`. The tokenizer only uses this surface, so implementing it directly keeps
 * the dialect tests headless and fast.
 */
class TestStream {
  pos = 0
  start = 0
  constructor(readonly string: string) {}

  sol(): boolean {
    return this.pos === 0
  }
  eol(): boolean {
    return this.pos >= this.string.length
  }
  peek(): string | null {
    return this.pos < this.string.length ? (this.string[this.pos] as string) : null
  }
  next(): string | undefined {
    return this.pos < this.string.length ? (this.string[this.pos++] as string) : undefined
  }
  eatSpace(): boolean {
    const from = this.pos
    while (this.pos < this.string.length && /\s/.test(this.string[this.pos] as string)) this.pos++
    return this.pos > from
  }
  skipToEnd(): void {
    this.pos = this.string.length
  }
  skipTo(text: string): boolean {
    const found = this.string.indexOf(text, this.pos)
    if (found === -1) return false
    this.pos = found
    return true
  }
  match(pattern: string | RegExp, consume = true): boolean | RegExpMatchArray | null {
    if (typeof pattern === 'string') {
      if (!this.string.startsWith(pattern, this.pos)) return false
      if (consume) this.pos += pattern.length
      return true
    }
    const result = pattern.exec(this.string.slice(this.pos))
    if (!result || result.index !== 0) return null
    if (consume) this.pos += result[0].length
    return result
  }
}

/** Runs the tokenizer over a source and returns the token names produced. */
function tokenize(id: string, source: string): string[] {
  const dialect = getDialect(id)
  if (!dialect) throw new Error(`no dialect for ${id}`)
  const parser = makeStreamParser(dialect.data)
  const state = parser.startState?.(2) as DialectState
  const tokens: string[] = []

  for (const line of source.split('\n')) {
    const stream = new TestStream(line)
    while (stream.pos < line.length) {
      stream.start = stream.pos
      const before = stream.pos
      const token = parser.token(stream as unknown as StringStream, state)
      if (stream.pos === before) break
      if (token) tokens.push(token)
    }
  }
  return tokens
}

