import { type RasterFormat, clampScale, rasterize } from './raster'
import { type SizedSvg, serializeSvg } from './svg'

export * from './svg'
export * from './raster'

/**
 * Client-side export. No server round trip, ever.
 *
 * - SVG: standalone serialization with CSS custom properties resolved.
 * - PNG / WEBP: rasterized through a canvas at a selectable scale.
 * - PDF: vector, via svg2pdf. Never a rasterized image pasted into a page.
 */

export type ExportFormat = 'svg' | 'png' | 'webp' | 'pdf'

export interface ExportOptions {
  format: ExportFormat
  /** Raster scale factor. Ignored for svg and pdf. */
  scale?: number
  /** Transparent when false. */
  background?: string | false
  /** Encoder quality for webp, 0–1. */
  quality?: number
  fileName?: string
}

export const DEFAULT_EXPORT_OPTIONS = {
  format: 'svg',
  scale: 2,
  background: false,
} as const satisfies ExportOptions

export const EXPORT_EXTENSIONS: Record<ExportFormat, string> = {
  svg: 'svg',
  png: 'png',
  webp: 'webp',
  pdf: 'pdf',
}

export interface ExportInput {
  svg: string
  viewBox: { x: number; y: number; width: number; height: number }
}

async function toPdf(sized: SizedSvg): Promise<Blob> {
  // Loaded on demand: jspdf plus svg2pdf is the single largest dependency in the app, and
  // most sessions never export a PDF.
  const [{ jsPDF }] = await Promise.all([import('jspdf'), import('svg2pdf.js')])

  const doc = new jsPDF({
    unit: 'pt',
    format: [sized.width, sized.height],
    orientation: sized.width >= sized.height ? 'landscape' : 'portrait',
  })

  const host = document.createElement('div')
  host.style.cssText = 'position:absolute;left:-99999px;top:0'
  host.innerHTML = sized.markup.replace(/^<\?xml[^>]*\?>\s*/, '')
  document.body.appendChild(host)

  try {
    const element = host.querySelector('svg')
    if (!element) throw new Error('Export failed: the diagram is not valid SVG.')
    await doc.svg(element, { x: 0, y: 0, width: sized.width, height: sized.height })
    return doc.output('blob')
  } finally {
    host.remove()
  }
}

/** Produces the exported file as a Blob. Does not touch the DOM beyond what it cleans up. */
export async function exportDiagram(input: ExportInput, options: ExportOptions): Promise<Blob> {
  const background = options.background ?? DEFAULT_EXPORT_OPTIONS.background
  const sized = serializeSvg(input.svg, input.viewBox, { background })

  switch (options.format) {
    case 'svg':
      return new Blob([sized.markup], { type: 'image/svg+xml;charset=utf-8' })
    case 'png':
    case 'webp':
      return rasterize(sized, {
        format: options.format as RasterFormat,
        scale: options.scale ?? DEFAULT_EXPORT_OPTIONS.scale,
        background,
        quality: options.quality,
      })
    case 'pdf':
      return toPdf(sized)
  }
}

/** Reports the raster size the user will actually get, after clamping. */
export function rasterDimensions(
  viewBox: { width: number; height: number },
  scale: number,
): { width: number; height: number; clamped: boolean } {
  const effective = clampScale(viewBox.width, viewBox.height, scale)
  return {
    width: Math.max(1, Math.round(viewBox.width * effective)),
    height: Math.max(1, Math.round(viewBox.height * effective)),
    clamped: effective !== scale,
  }
}

export function downloadBlob(blob: Blob, fileName: string): void {
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = fileName
  anchor.rel = 'noopener'
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  // Revoked on the next task so the download has started.
  setTimeout(() => URL.revokeObjectURL(url), 0)
}

/** A safe, meaningful file name from a diagram name. */
export function exportFileName(name: string, format: ExportFormat): string {
  const base =
    name
      .trim()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .slice(0, 80) || 'diagram'
  return `${base}.${EXPORT_EXTENSIONS[format]}`
}

import type { IDBPDatabase, IDBPTransaction } from 'idb'
import type { WorkspaceSchema } from './schema'

/**
 * Storage migrations.
 *
 * Rules, identical to the ones we would apply against Postgres:
 *
 * - One numbered migration per change. Never edit one that has shipped.
 * - Forward-only and idempotent — `upgradeneeded` can run at any starting version.
 * - Never rename or repurpose a store in place. Add, backfill, then retire later.
 * - A migration that can lose a diagram is a defect, not a trade-off.
 */

export interface Migration {
  readonly version: number
  readonly description: string
  run(
    db: IDBPDatabase<WorkspaceSchema>,
    tx: IDBPTransaction<WorkspaceSchema, ArrayLike<never>, 'versionchange'>,
  ): void
}

export const MIGRATIONS: readonly Migration[] = [
  {
    version: 1,
    description: 'Initial workspace: documents, revisions, folders, preferences, blobs.',
    run(db) {
      if (!db.objectStoreNames.contains('documents')) {
        const documents = db.createObjectStore('documents', { keyPath: 'id' })
        documents.createIndex('by-updated', 'updatedAt')
        documents.createIndex('by-type', 'typeId')
        documents.createIndex('by-folder', 'folderId')
      }
      if (!db.objectStoreNames.contains('revisions')) {
        const revisions = db.createObjectStore('revisions', { keyPath: ['documentId', 'seq'] })
        revisions.createIndex('by-document', 'documentId')
      }
      if (!db.objectStoreNames.contains('folders')) {
        db.createObjectStore('folders', { keyPath: 'id' })
      }
      if (!db.objectStoreNames.contains('preferences')) {
        db.createObjectStore('preferences', { keyPath: 'key' })
      }
      if (!db.objectStoreNames.contains('blobs')) {
        db.createObjectStore('blobs', { keyPath: 'id' })
      }
    },
  },
]

export function runMigrations(
  db: IDBPDatabase<WorkspaceSchema>,
  tx: IDBPTransaction<WorkspaceSchema, ArrayLike<never>, 'versionchange'>,
  from: number,
  to: number,
): void {
  for (const migration of MIGRATIONS) {
    if (migration.version > from && migration.version <= to) migration.run(db, tx)
  }
}

