import type { IDBPDatabase, IDBPTransaction, StoreNames } from 'idb'
import type { WorkspaceSchema } from './schema'

/** The transaction `upgradeneeded` hands to a migration: every store, versionchange mode. */
export type UpgradeTransaction = IDBPTransaction<
  WorkspaceSchema,
  StoreNames<WorkspaceSchema>[],
  'versionchange'
>

/**
 * Storage migrations.
 *
 * Rules, identical to the ones we would apply against Postgres:
 *
 * - One numbered migration per change. Never edit one that has shipped.
 * - Forward-only and idempotent — `upgradeneeded` can run at any starting version.
 * - Never rename or repurpose a store in place. Add, backfill, then retire later.
 * - A migration that can lose a diagram is a defect, not a trade-off.
 */

export interface Migration {
  readonly version: number
  readonly description: string
  run(db: IDBPDatabase<WorkspaceSchema>, tx: UpgradeTransaction): void
}

export const MIGRATIONS: readonly Migration[] = [
  {
    version: 1,
    description: 'Initial workspace: documents, revisions, folders, preferences, blobs.',
    run(db) {
      if (!db.objectStoreNames.contains('documents')) {
        const documents = db.createObjectStore('documents', { keyPath: 'id' })
        documents.createIndex('by-updated', 'updatedAt')
        documents.createIndex('by-type', 'typeId')
        documents.createIndex('by-folder', 'folderId')
      }
      if (!db.objectStoreNames.contains('revisions')) {
        const revisions = db.createObjectStore('revisions', { keyPath: ['documentId', 'seq'] })
        revisions.createIndex('by-document', 'documentId')
      }
      if (!db.objectStoreNames.contains('folders')) {
        db.createObjectStore('folders', { keyPath: 'id' })
      }
      if (!db.objectStoreNames.contains('preferences')) {
        db.createObjectStore('preferences', { keyPath: 'key' })
      }
      if (!db.objectStoreNames.contains('blobs')) {
        db.createObjectStore('blobs', { keyPath: 'id' })
      }
    },
  },
]

export function runMigrations(
  db: IDBPDatabase<WorkspaceSchema>,
  tx: IDBPTransaction<WorkspaceSchema, ArrayLike<never>, 'versionchange'>,
  from: number,
  to: number,
): void {
  for (const migration of MIGRATIONS) {
    if (migration.version > from && migration.version <= to) migration.run(db, tx)
  }
}

