import { autocompletion, closeBrackets, closeBracketsKeymap } from '@codemirror/autocomplete'
import { defaultKeymap, history, historyKeymap, indentWithTab } from '@codemirror/commands'
import { bracketMatching, foldGutter, foldKeymap, indentOnInput } from '@codemirror/language'
import { lintGutter, setDiagnostics } from '@codemirror/lint'
import { Compartment, EditorState } from '@codemirror/state'
import { highlightSelectionMatches, searchKeymap } from '@codemirror/search'
import {
  EditorView,
  drawSelection,
  highlightActiveLine,
  highlightActiveLineGutter,
  keymap,
  lineNumbers,
} from '@codemirror/view'
import type { RenderError } from '@mr/core'
import { getDialect, mermaidCompletion } from '@mr/editor'
import { useEffect, useRef } from 'react'

interface Props {
  value: string
  onChange: (next: string) => void
  /** Detected diagram type, or null when the document has no recognizable header. */
  typeId: string | null
  /** Normalized parse/render error, placed on its line in the gutter. */
  error: RenderError | null
}

/**
 * The text editor.
 *
 * The language and the completion source are held in compartments and reconfigured when
 * the detected diagram type changes, so switching from a flowchart to a sequence diagram
 * swaps the dialect without losing undo history or cursor position.
 */
export function CodeEditor({ value, onChange, typeId, error }: Props) {
  const host = useRef<HTMLDivElement | null>(null)
  const view = useRef<EditorView | null>(null)
  const language = useRef(new Compartment())
  const completion = useRef(new Compartment())
  const onChangeRef = useRef(onChange)
  onChangeRef.current = onChange
  const initialDoc = useRef(value)
  const initialType = useRef(typeId)

  useEffect(() => {
    if (!host.current) return

    const dialect = initialType.current ? getDialect(initialType.current) : undefined

    const state = EditorState.create({
      doc: initialDoc.current,
      extensions: [
        lineNumbers(),
        highlightActiveLineGutter(),
        foldGutter(),
        lintGutter(),
        history(),
        drawSelection(),
        indentOnInput(),
        bracketMatching(),
        closeBrackets(),
        highlightActiveLine(),
        highlightSelectionMatches(),
        keymap.of([
          ...closeBracketsKeymap,
          ...defaultKeymap,
          ...historyKeymap,
          ...searchKeymap,
          ...foldKeymap,
          indentWithTab,
        ]),
        language.current.of(dialect ? [dialect.language] : []),
        completion.current.of(
          autocompletion({ override: [mermaidCompletion(initialType.current)] }),
        ),
        EditorView.lineWrapping,
        EditorView.updateListener.of((update) => {
          if (update.docChanged) onChangeRef.current(update.state.doc.toString())
        }),
        EditorView.theme({
          '&': { height: '100%', fontSize: '13px', backgroundColor: 'transparent' },
          '.cm-scroller': { fontFamily: 'var(--font-mono)', lineHeight: '1.7' },
          '.cm-gutters': {
            backgroundColor: 'transparent',
            border: 'none',
            color: 'var(--muted-foreground)',
          },
          '.cm-activeLine': { backgroundColor: 'var(--muted)' },
          '.cm-activeLineGutter': { backgroundColor: 'transparent', color: 'var(--foreground)' },
          '.cm-content': { caretColor: 'var(--primary)' },
          '.cm-tooltip': {
            backgroundColor: 'var(--surface-raised)',
            border: '1px solid var(--border)',
            borderRadius: 'var(--radius-app)',
          },
        }),
      ],
    })

    const instance = new EditorView({ state, parent: host.current })
    view.current = instance
    return () => {
      instance.destroy()
      view.current = null
    }
  }, [])

  // External document changes, such as opening a different diagram.
  useEffect(() => {
    const instance = view.current
    if (!instance) return
    const current = instance.state.doc.toString()
    if (current === value) return
    instance.dispatch({ changes: { from: 0, to: current.length, insert: value } })
  }, [value])

  // Swap the dialect when the detected type changes.
  useEffect(() => {
    const instance = view.current
    if (!instance) return
    const dialect = typeId ? getDialect(typeId) : undefined
    instance.dispatch({
      effects: [
        language.current.reconfigure(dialect ? [dialect.language] : []),
        completion.current.reconfigure(autocompletion({ override: [mermaidCompletion(typeId)] })),
      ],
    })
  }, [typeId])

  // Place the normalized error on its line, keeping the preview untouched.
  useEffect(() => {
    const instance = view.current
    if (!instance) return
    if (!error) {
      instance.dispatch(setDiagnostics(instance.state, []))
      return
    }
    const lineCount = instance.state.doc.lines
    const lineNumber = Math.min(Math.max(error.line ?? 1, 1), lineCount)
    const line = instance.state.doc.line(lineNumber)
    const from = error.column !== undefined ? Math.min(line.from + error.column, line.to) : line.from
    instance.dispatch(
      setDiagnostics(instance.state, [
        { from, to: line.to, severity: 'error', message: error.message },
      ]),
    )
  }, [error])

  return <div ref={host} className="h-full min-h-0 overflow-auto" />
}

