import type { DiagramDocument } from '@mr/core'
import { starterFor } from '@mr/editor'
import { QuotaExceededError, type Workspace, createIndexedDbWorkspace } from '@mr/storage'
import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * Workspace access for the application.
 *
 * Everything goes through the ports in `@mr/storage`; nothing here knows about IndexedDB.
 * When phase 2 adds a server it implements the same ports and this file does not change.
 */

let workspacePromise: Promise<Workspace> | null = null

export function getWorkspace(): Promise<Workspace> {
  workspacePromise ??= createIndexedDbWorkspace()
  return workspacePromise
}

export type SaveState = 'idle' | 'saving' | 'saved' | 'error'

const AUTOSAVE_MS = 700

export interface WorkspaceHandle {
  document: DiagramDocument | null
  saveState: SaveState
  saveError: string | null
  ready: boolean
  setBody(body: string): void
  rename(name: string): Promise<void>
  createFromType(typeId: string, keyword: string): Promise<void>
}

/**
 * Loads the most recent diagram, or seeds a first one, and autosaves edits.
 *
 * A failed write is surfaced with the content still in the editor — never a silent loss.
 */
export function useWorkspace(body: string, setBody: (next: string) => void): WorkspaceHandle {
  const [document, setDocument] = useState<DiagramDocument | null>(null)
  const [saveState, setSaveState] = useState<SaveState>('idle')
  const [saveError, setSaveError] = useState<string | null>(null)
  const [ready, setReady] = useState(false)
  const loaded = useRef(false)

  useEffect(() => {
    if (loaded.current) return
    loaded.current = true

    void (async () => {
      try {
        const workspace = await getWorkspace()
        const page = await workspace.documents.list({ limit: 1 })
        const existing = page.items[0]
        if (existing) {
          setDocument(existing)
          setBody(existing.body)
        } else {
          const created = await workspace.documents.create({
            name: 'Untitled diagram',
            body,
          })
          setDocument(created)
        }
        void workspace.requestPersistence()
      } catch (error) {
        setSaveError(error instanceof Error ? error.message : 'Local storage is unavailable.')
        setSaveState('error')
      } finally {
        setReady(true)
      }
    })()
  }, [body, setBody])

  // Autosave.
  useEffect(() => {
    if (!document || document.body === body) return
    setSaveState('saving')
    const timer = setTimeout(() => {
      void (async () => {
        try {
          const workspace = await getWorkspace()
          const next = await workspace.documents.update(document.id, { body })
          setDocument(next)
          setSaveState('saved')
          setSaveError(null)
        } catch (error) {
          setSaveState('error')
          setSaveError(
            error instanceof QuotaExceededError
              ? 'Out of storage space. Your work is still in the editor — free some space and it will save.'
              : 'Could not save. Your work is still in the editor.',
          )
        }
      })()
    }, AUTOSAVE_MS)
    return () => clearTimeout(timer)
  }, [body, document])

  const rename = useCallback(
    async (name: string) => {
      if (!document) return
      const workspace = await getWorkspace()
      setDocument(await workspace.documents.update(document.id, { name }))
    },
    [document],
  )

  const createFromType = useCallback(async (typeId: string, keyword: string) => {
    const starter = starterFor(typeId) ?? `${keyword}\n`
    const workspace = await getWorkspace()
    const created = await workspace.documents.create({ name: 'Untitled diagram', body: starter })
    setDocument(created)
    setBody(created.body)
  }, [setBody])

  return { document, saveState, saveError, ready, setBody, rename, createFromType }
}

