import {
  type ExportFormat,
  downloadBlob,
  exportDiagram,
  exportFileName,
  rasterDimensions,
} from '@mr/export'
import { useEffect, useMemo, useState } from 'react'
import type { RenderResult } from '../lib/render-host'

interface Props {
  result: RenderResult
  name: string
  onClose: () => void
}

const FORMATS: ReadonlyArray<{ id: ExportFormat; label: string; detail: string }> = [
  { id: 'svg', label: 'SVG', detail: 'Vector, opens anywhere' },
  { id: 'png', label: 'PNG', detail: 'Raster, transparent by default' },
  { id: 'webp', label: 'WEBP', detail: 'Raster, smaller files' },
  { id: 'pdf', label: 'PDF', detail: 'Vector, not a pasted image' },
]

const SCALES = [1, 2, 3, 4] as const

export function ExportDialog({ result, name, onClose }: Props) {
  const [format, setFormat] = useState<ExportFormat>('svg')
  const [scale, setScale] = useState<number>(2)
  const [opaque, setOpaque] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const isRaster = format === 'png' || format === 'webp'
  const size = useMemo(() => rasterDimensions(result.viewBox, scale), [result.viewBox, scale])

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onClose])

  async function run() {
    setBusy(true)
    setError(null)
    try {
      const background = opaque
        ? getComputedStyle(document.documentElement).getPropertyValue('--background').trim()
        : false
      const blob = await exportDiagram(
        { svg: result.svg, viewBox: result.viewBox },
        { format, scale, background },
      )
      downloadBlob(blob, exportFileName(name, format))
      onClose()
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : 'Export failed.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"
      role="dialog"
      aria-modal="true"
      aria-label="Export diagram"
    >
      <div className="w-full max-w-md rounded-app border bg-surface-raised p-4 shadow-xl">
        <h2 className="font-medium text-sm">Export</h2>

        <fieldset className="mt-3">
          <legend className="sr-only">Format</legend>
          <div className="grid grid-cols-2 gap-2">
            {FORMATS.map((option) => (
              <button
