import { DIAGRAM_TYPES } from '@mr/core'
import { useEffect, useMemo, useRef, useState } from 'react'

interface Props {
  onPick: (typeId: string, keyword: string) => void
  onClose: () => void
}

/**
 * The diagram-type picker: all 32 documented types, each with its version gate and
 * experimental marking. `info` is excluded — it renders the mermaid version and is not a
 * diagram anyone authors deliberately.
 */
export function TypePicker({ onPick, onClose }: Props) {
  const [query, setQuery] = useState('')
  const input = useRef<HTMLInputElement | null>(null)

  useEffect(() => {
    input.current?.focus()
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onClose])

  const matches = useMemo(() => {
    const needle = query.trim().toLowerCase()
    return DIAGRAM_TYPES.filter((type) => type.doc !== null).filter(
      (type) =>
        needle === '' ||
        type.label.toLowerCase().includes(needle) ||
        type.keyword.toLowerCase().includes(needle),
    )
  }, [query])

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center bg-black/40 p-4 pt-[12vh]"
      role="dialog"
      aria-modal="true"
      aria-label="New diagram"
    >
      <div className="flex max-h-[70vh] w-full max-w-lg flex-col rounded-app border bg-surface-raised shadow-xl">
        <input
          ref={input}
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Search 32 diagram types…"
          aria-label="Search diagram types"
          className="border-b bg-transparent px-4 py-3 text-sm outline-none"
        />
        <ul className="min-h-0 flex-1 overflow-auto p-1">
          {matches.map((type) => (
            <li key={type.id}>
              <button
                type="button"
                onClick={() => onPick(type.id, type.keyword)}
                className="flex w-full items-baseline gap-2 rounded-app px-3 py-2 text-left text-sm hover:bg-muted"
              >
                <span className="font-medium">{type.label}</span>
                <code className="text-muted-foreground text-xs">{type.keyword}</code>
                {type.beta && <span className="text-warning text-xs">experimental</span>}
                {type.external && <span className="text-danger text-xs">needs a plugin</span>}
                {type.minVersion && (
                  <span className="ml-auto tabular-nums text-muted-foreground text-xs">
                    v{type.minVersion}+
                  </span>
                )}
              </button>
            </li>
          ))}
          {matches.length === 0 && (
            <li className="px-3 py-6 text-center text-muted-foreground text-sm">
              No diagram type matches “{query}”.
            </li>
          )}
        </ul>
      </div>
    </div>
  )
}

