import { expect, test } from '@playwright/test'
import { DIAGRAM_TYPES } from '@mr/core'
import { starterFor } from '@mr/editor'

/**
 * Ground truth for "does it actually render".
 *
 * Unit tests cannot answer this: mermaid needs a real layout engine, so the only way to
 * know a diagram renders is to open a browser and look. A clean build proves nothing here.
 */

const canvas = '[data-testid="diagram-canvas"] svg'

async function setEditorText(page: import('@playwright/test').Page, text: string) {
  await page.evaluate((value) => {
    const target = window as unknown as { __setEditorText?: (next: string) => void }
    target.__setEditorText?.(value)
  }, text)
}

test.beforeEach(async ({ page }) => {
  await page.addInitScript(() => {
    window.localStorage.clear()
    indexedDB.deleteDatabase('mermaid-render')
  })
})

test('boots the render frame and draws the starter diagram', async ({ page }) => {
  const errors: string[] = []
  page.on('pageerror', (error) => errors.push(error.message))
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text())
  })

  await page.goto('/')

  await expect(page.locator(canvas)).toBeVisible({ timeout: 20_000 })
  await expect(page.getByText(/mermaid 11\.16\.1/)).toBeVisible()
  expect(errors.filter((e) => !e.includes('favicon'))).toEqual([])
})

test('keeps the last good render when the source stops parsing', async ({ page }) => {
  await page.goto('/')
  await expect(page.locator(canvas)).toBeVisible({ timeout: 20_000 })

  await setEditorText(page, 'flowchart TD\n    A --> ((( broken')

  // The canvas must survive; the error goes to the status bar, not the picture.
  await expect(page.getByText('Cannot render')).toBeVisible({ timeout: 10_000 })
  await expect(page.locator(canvas)).toBeVisible()
})

test('makes no outbound network requests', async ({ page }) => {
  const external: string[] = []
  page.on('request', (request) => {
    const url = new URL(request.url())
    if (url.hostname !== 'localhost' && url.protocol !== 'data:' && url.protocol !== 'blob:') {
      external.push(request.url())
    }
  })

  await page.goto('/')
  await expect(page.locator(canvas)).toBeVisible({ timeout: 20_000 })
  expect(external).toEqual([])
})

// Every type in the catalog must render its own starter. This is the test that turns
// "33 types supported" from a claim into a fact.
const renderable = DIAGRAM_TYPES.filter((type) => type.doc !== null && !type.external)

for (const type of renderable) {
  test(`renders the ${type.id} starter`, async ({ page }) => {
    await page.goto('/')
    await expect(page.locator(canvas)).toBeVisible({ timeout: 20_000 })

    await setEditorText(page, starterFor(type.id) as string)

    await expect(page.locator(canvas)).toBeVisible({ timeout: 15_000 })
    await expect(page.getByText('Cannot render')).toHaveCount(0)
  })
}

