import { useCallback, useEffect, useRef, useState } from 'react'
import type { RenderResult } from '../lib/render-host'

interface Props {
  result: RenderResult | null
  pending: boolean
}

interface View {
  x: number
  y: number
  zoom: number
}

const MIN_ZOOM = 0.05
const MAX_ZOOM = 16

/**
 * The canvas.
 *
 * Pan and zoom are a CSS transform on a single container, so moving around a large
 * diagram costs no layout. The SVG is inserted as a node, never as a data URL.
 */
export function DiagramCanvas({ result, pending }: Props) {
  const surface = useRef<HTMLDivElement | null>(null)
  const stage = useRef<HTMLDivElement | null>(null)
  const [view, setView] = useState<View>({ x: 0, y: 0, zoom: 1 })
  const drag = useRef<{ x: number; y: number; ox: number; oy: number } | null>(null)

  useEffect(() => {
    const node = stage.current
    if (!node || !result) return
    // Already sanitized on the host, in RenderHost, before it reached this component.
    node.innerHTML = result.svg
    const svg = node.querySelector('svg')
    if (svg) {
      svg.removeAttribute('width')
      svg.removeAttribute('height')
      svg.style.maxWidth = 'none'
      svg.style.display = 'block'
    }
  }, [result])

  const fit = useCallback(() => {
    const box = surface.current?.getBoundingClientRect()
    if (!box || !result) return
    const { width, height } = result.viewBox
    if (width <= 0 || height <= 0) return
    const zoom = Math.min((box.width - 64) / width, (box.height - 64) / height, 1)
    setView({
      x: (box.width - width * zoom) / 2,
      y: (box.height - height * zoom) / 2,
      zoom,
    })
  }, [result])

  useEffect(() => {
    fit()
  }, [fit])

  const onWheel = useCallback((event: React.WheelEvent) => {
    event.preventDefault()
    const box = event.currentTarget.getBoundingClientRect()
    const px = event.clientX - box.left
    const py = event.clientY - box.top
    setView((prev) => {
      const factor = Math.exp(-event.deltaY * 0.0015)
      const zoom = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, prev.zoom * factor))
      const ratio = zoom / prev.zoom
      return { zoom, x: px - (px - prev.x) * ratio, y: py - (py - prev.y) * ratio }
    })
  }, [])

  const onPointerDown = useCallback((event: React.PointerEvent) => {
    if (event.button !== 0) return
    event.currentTarget.setPointerCapture(event.pointerId)
    drag.current = { x: event.clientX, y: event.clientY, ox: 0, oy: 0 }
    setView((prev) => {
      const d = drag.current
      if (d) {
        d.ox = prev.x
        d.oy = prev.y
      }
      return prev
    })
  }, [])

  const onPointerMove = useCallback((event: React.PointerEvent) => {
    const d = drag.current
    if (!d) return
    setView((prev) => ({
      ...prev,
      x: d.ox + (event.clientX - d.x),
      y: d.oy + (event.clientY - d.y),
    }))
  }, [])

  const onPointerUp = useCallback(() => {
    drag.current = null
  }, [])

  return (
    <div
      ref={surface}
      className="relative h-full min-h-0 overflow-hidden bg-surface"
      onWheel={onWheel}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      style={{ cursor: drag.current ? 'grabbing' : 'grab', touchAction: 'none' }}
    >
      <div
        ref={stage}
        className="absolute origin-top-left transition-opacity"
        style={{
          transform: `translate(${view.x}px, ${view.y}px) scale(${view.zoom})`,
          // Dimmed, never blanked, while a new render is in flight.
          opacity: pending && result ? 0.55 : 1,
        }}
      />

      {!result && (
        <p className="absolute inset-0 flex items-center justify-center text-muted-foreground text-sm">
          {pending ? 'Rendering…' : 'Nothing to show yet'}
        </p>
      )}

      <div className="absolute right-3 bottom-3 flex items-center gap-1 rounded-app border bg-surface-raised px-2 py-1 text-xs">
        <button type="button" className="px-1.5 hover:text-primary" onClick={fit}>
          Fit
        </button>
        <span className="w-12 text-right tabular-nums text-muted-foreground">
          {Math.round(view.zoom * 100)}%
        </span>
      </div>
    </div>
  )
}

