/**
 * The bridge between the application token set and Mermaid's theme variables.
 *
 * Both sides read from the CSS variables declared in styles.css, so switching to dark
 * mode moves the interface and the diagram together, from the same source values. This
 * function is the only place allowed to know Mermaid's variable names.
 *
 * Reference for the variable names:
 * mermaid-upstream/packages/mermaid/src/docs/config/theming.md
 */

const TOKEN_TO_MERMAID: ReadonlyArray<readonly [string, readonly string[]]> = [
  ['--diagram-background', ['background']],
  ['--diagram-node', ['primaryColor', 'mainBkg']],
  ['--diagram-node-border', ['primaryBorderColor', 'nodeBorder']],
  ['--diagram-text', ['primaryTextColor', 'textColor', 'nodeTextColor']],
  ['--diagram-line', ['lineColor', 'defaultLinkColor']],
  ['--diagram-cluster', ['clusterBkg']],
  ['--border', ['clusterBorder']],
  ['--font-sans', ['fontFamily']],
]

/**
 * Converts a CSS color into a legacy sRGB notation mermaid can parse.
 *
 * Required, not cosmetic: our tokens are declared in `oklch`, and mermaid's theme layer
 * (khroma) throws `Unsupported color format: "oklch(…)"`, which aborts the whole render.
 *
 * `getComputedStyle` does **not** solve this. Under CSS Color 4 the computed value of a
 * non-legacy color keeps its color space, so an `oklch` token comes back as `oklch`. A
 * canvas context does solve it: `fillStyle` always serializes to `#rrggbb` or `rgba()`.
 */
const colorCache = new Map<string, string>()

function toRenderableColor(value: string): string {
  const cached = colorCache.get(value)
  if (cached !== undefined) return cached

  const context = document.createElement('canvas').getContext('2d')
  if (!context) return value

  // A sentinel the value is unlikely to equal, so an unparseable color is detectable:
  // assigning an invalid color leaves fillStyle untouched.
  const sentinel = '#010203'
  context.fillStyle = sentinel
  context.fillStyle = value
  const serialized = context.fillStyle
  const result = serialized === sentinel && value.trim() !== sentinel ? value : serialized

  colorCache.set(value, result)
  return result
}

/** Clears the conversion cache. Call when the theme changes. */
export function resetColorCache(): void {
  colorCache.clear()
}

/** Tokens whose value is not a color and must be passed through untouched. */
const NON_COLOR_TOKENS = new Set(['--font-sans', '--font-mono'])

/** Resolves the current token values into Mermaid `themeVariables`. */
export function mermaidThemeVariables(
  scope: Element = document.documentElement,
): Record<string, string> {
  const styles = getComputedStyle(scope)
  const variables: Record<string, string> = {}
  for (const [token, targets] of TOKEN_TO_MERMAID) {
    const raw = styles.getPropertyValue(token).trim()
    if (raw === '') continue
    const value = NON_COLOR_TOKENS.has(token) ? raw : toRenderableColor(raw)
    for (const target of targets) variables[target] = value
  }
  return variables
}

