const railroadOperator: Rule = (doc) => {
  const header = doc.code.find((line) => line.trim() !== '')?.trim() ?? ''
  const isEbnf = header.startsWith('railroad-ebnf')
  const isSlashChoice = header.startsWith('railroad-abnf') || header.startsWith('railroad-peg')
  if (!isEbnf && !isSlashChoice) return []

  const wrong = isEbnf ? '/' : '|'
  const right = isEbnf ? '|' : '/'
  const found: EditorDiagnostic[] = []
  doc.code.forEach((line, index) => {
    // Ignore anything inside quotes, where the character is literal.
    const stripped = line.replace(/"[^"]*"|'[^']*'/g, (m) => ' '.repeat(m.length))
    const column = stripped.indexOf(wrong)
    if (column === -1) return
    found.push(
      at(
        index,
        column,
        column + 1,
        'error',
        'railroad/wrong-choice-operator',
        `This notation uses "${right}" for choice, not "${wrong}".`,
      ),
    )
  })
  return found
}

