const RULES: Record<string, readonly Rule[]> = {
  flowchart: [lowercaseEnd, edgeSwallowsNode],
  swimlanes: [lowercaseEnd, edgeSwallowsNode],
  block: [edgeSwallowsNode],
  sequence: [lowercaseEnd],
  gantt: [ganttDuration, ganttWeekdays, ganttUnknownTask],
  pie: [pieValues],
  venn: [vennUnknownSet],
  quadrant: [quadrantRange],
  wardley: [wardleyRange],
  cynefin: [cynefinRules],
  kanban: [kanbanPriority],
  xychart: [xychartBarLabel],
  sankey: [sankeyColumns],
  treemap: [treemapNegative],
  radar: [radarGraticule],
  railroad: [railroadOperator],
}

/** Diagram types that have at least one rule. Everything else returns no diagnostics. */
export function typesWithDiagnostics(): readonly string[] {
  return Object.keys(RULES)
}

export function diagnose(text: string, typeId: string | null): EditorDiagnostic[] {
  if (!typeId) return []
  const rules = RULES[typeId]
  if (!rules) return []
  const doc = buildDoc(text)
  return rules.flatMap((rule) => rule(doc)).sort((a, b) => a.line - b.line || a.from - b.from)
}

