import { stripPreamble } from '@mr/core'

/**
 * Per-dialect diagnostics.
 *
 * These are the checks mermaid does not make, or makes so badly the message is useless.
 * Every rule cites the upstream page it comes from, and every rule catches something that
 * otherwise fails *silently* — a task that renders as zero length, a label that is
 * accepted and ignored, a link that quietly becomes a different shape.
 *
 * A rule that duplicates mermaid's own parse error does not belong here. The parser is
 * the source of truth for validity; this file is for what the parser lets through.
 */

export type Severity = 'error' | 'warning' | 'info'

export interface EditorDiagnostic {
  /** 1-based, to match how mermaid and the editor gutter count. */
  line: number
  /** 0-based column range within the line. */
  from: number
  to: number
  severity: Severity
  message: string
  ruleId: string
}

interface Doc {
  /** Lines of the original text, so reported line numbers match what the user sees. */
  readonly lines: readonly string[]
  /** Lines with frontmatter, directives and comments blanked out. */
  readonly code: readonly string[]
  readonly text: string
}

type Rule = (doc: Doc) => EditorDiagnostic[]

function at(
  line: number,
  from: number,
  to: number,
  severity: Severity,
  ruleId: string,
  message: string,
): EditorDiagnostic {
  return { line: line + 1, from, to, severity, ruleId, message }
}

/** Blanks out comments so rules never match inside them. */
function buildDoc(text: string): Doc {
  const lines = text.split('\n')
  const preambleLength = text.length - stripPreamble(text).length
  let consumed = 0
  const code = lines.map((line) => {
    const isPreamble = consumed < preambleLength
    consumed += line.length + 1
    if (isPreamble) return ' '.repeat(line.length)
    const comment = line.indexOf('%%')
    return comment === -1 ? line : line.slice(0, comment) + ' '.repeat(line.length - comment)
  })
  return { lines, code, text }
}

// ---------------------------------------------------------------------------
// flowchart, and the dialects that reuse its node and edge syntax
// ---------------------------------------------------------------------------

/** flowchart.md:9-11 — a lowercase `end` breaks the diagram outright. */
const lowercaseEnd: Rule = (doc) => {
  const found: EditorDiagnostic[] = []
  doc.code.forEach((line, index) => {
    for (const match of line.matchAll(/(^|[[({>|\s])end([\])}|\s]|$)/g)) {
      const column = (match.index ?? 0) + match[1].length
      // A block terminator on its own line is the legitimate use.
      if (line.trim() === 'end') continue
      found.push(
        at(
          index,
          column,
          column + 3,
          'error',
          'flowchart/lowercase-end',
          'A lowercase "end" breaks the diagram. Write "End" or "END".',
        ),
      )
    }
  })
  return found
}

/** flowchart.md:13-19 — `A---oB` is a circle edge, not a node called `oB`. */
const edgeSwallowsNode: Rule = (doc) => {
  const found: EditorDiagnostic[] = []
  doc.code.forEach((line, index) => {
    for (const match of line.matchAll(/-{2,}([ox])(?=[A-Za-z_])/g)) {
      const column = (match.index ?? 0) + match[0].length - 1
      const kind = match[1] === 'o' ? 'circle' : 'cross'
      found.push(
        at(
          index,
          column,
          column + 1,
          'warning',
          'flowchart/edge-swallows-node',
          `This reads as a ${kind} edge, not a node starting with "${match[1]}". Add a space or capitalise the letter.`,
        ),
      )
    }
  })
  return found
}

// ---------------------------------------------------------------------------
// gantt
// ---------------------------------------------------------------------------

const DURATION = /^\d+(\.\d+)?(ms|[smhdwMy])$/

/** gantt.md:113 — an invalid duration is ignored and the task becomes zero length. */
const ganttDuration: Rule = (doc) => {
  const found: EditorDiagnostic[] = []
  doc.code.forEach((line, index) => {
    const colon = line.indexOf(':')
    if (colon === -1) return
    const head = line.slice(0, colon).trim()
    if (head === '' || /^(title|dateFormat|axisFormat|tickInterval|weekday|excludes|section)\b/.test(head)) return

    for (const raw of line.slice(colon + 1).split(',')) {
      const token = raw.trim()
      if (!/^\d/.test(token)) continue
      if (DURATION.test(token)) continue
      const column = line.indexOf(token, colon)
      found.push(
        at(
          index,
          column,
          column + token.length,
          'error',
          'gantt/invalid-duration',
          `"${token}" is not a valid duration, so this task silently becomes zero length. Use a number plus ms, s, m, h, d, w, M or y.`,
        ),
      )
    }
  })
  return found
}

/** gantt.md:131 — `excludes` accepts dates, weekday names or "weekends", never "weekdays". */
const ganttWeekdays: Rule = (doc) => {
  const found: EditorDiagnostic[] = []
  doc.code.forEach((line, index) => {
    const match = /^\s*excludes\b.*\b(weekdays)\b/.exec(line)
    if (!match) return
    const column = line.indexOf('weekdays')
    found.push(
      at(
        index,
        column,
        column + 8,
        'error',
        'gantt/excludes-weekdays',
        '"weekdays" is not supported. Use "weekends", a weekday name such as "sunday", or explicit dates.',
