    const value = Number(match[2])
    const column = line.lastIndexOf(match[2] as string)
    if (value <= 0) {
      found.push(
        at(
          index,
          column,
          column + (match[2] as string).length,
          'error',
          'pie/non-positive-value',
          'Pie values must be greater than zero. Zero and negative values are an error.',
        ),
      )
    } else if (/\.\d{3,}$/.test(match[2] as string)) {
      found.push(
        at(
          index,
          column,
          column + (match[2] as string).length,
          'warning',
          'pie/precision',
          'Pie values support at most two decimal places.',
        ),
      )
    }
  })
  return found
