import { DIAGRAM_TYPES } from '@mr/core'
import { describe, expect, test } from 'bun:test'
import { diagnose, typesWithDiagnostics } from './diagnostics'
import { starterFor } from './dialects/registry'

/** Rule ids reported for a source, for terse assertions. */
function ids(text: string, typeId: string): string[] {
  return diagnose(text, typeId).map((d) => d.ruleId)
}

describe('no false positives on the canonical starters', () => {
  // The strongest guard there is: every starter is known-good and must stay silent.
  for (const type of DIAGRAM_TYPES) {
    test(`${type.id} starter produces no diagnostics`, () => {
      expect(diagnose(starterFor(type.id) as string, type.id)).toEqual([])
    })
  }
})

describe('rules only run for their own dialect', () => {
  test('returns nothing for an unknown or absent type', () => {
    expect(diagnose('pie\n"a" : -1', null)).toEqual([])
    expect(diagnose('pie\n"a" : -1', 'mindmap')).toEqual([])
  })

  test('every registered type id exists in the catalog', () => {
    const known = new Set(DIAGRAM_TYPES.map((t) => t.id))
    expect(typesWithDiagnostics().filter((id) => !known.has(id as never))).toEqual([])
  })
})

describe('flowchart', () => {
  test('flags a lowercase end, which breaks the diagram', () => {
    expect(ids('flowchart TD\n    A --> end', 'flowchart')).toEqual(['flowchart/lowercase-end'])
  })

  test('allows End and END', () => {
    expect(ids('flowchart TD\n    A --> End\n    B --> END', 'flowchart')).toEqual([])
  })

  test('allows end as a subgraph terminator', () => {
    expect(ids('flowchart TD\n  subgraph one\n    a --> b\n  end', 'flowchart')).toEqual([])
  })

  test('flags a node that the edge swallows', () => {
    expect(ids('flowchart LR\n    dev---ops', 'flowchart')).toEqual([
      'flowchart/edge-swallows-node',
    ])
  })

  test('accepts the documented workaround', () => {
    expect(ids('flowchart LR\n    dev--- ops\n    dev---Ops', 'flowchart')).toEqual([])
  })

  test('ignores anything inside a comment', () => {
    expect(ids('flowchart TD\n%% A --> end and dev---ops', 'flowchart')).toEqual([])
  })
})

describe('gantt', () => {
  test('flags a duration that silently becomes zero length', () => {
    expect(ids('gantt\n    Task :a1, 2026-01-01, 3dX', 'gantt')).toContain('gantt/invalid-duration')
  })

  test('accepts every documented unit, including decimals', () => {
    const source = [
      'gantt',
      '    A :500ms',
      '    B :30s',
      '    C :30m',
      '    D :4h',
      '    E :1.5d',
      '    F :2w',
      '    G :1M',
      '    H :1y',
    ].join('\n')
    expect(ids(source, 'gantt')).toEqual([])
  })

  test('flags excludes weekdays, which is explicitly unsupported', () => {
    expect(ids('gantt\n    excludes weekdays', 'gantt')).toEqual(['gantt/excludes-weekdays'])
  })

  test('accepts excludes weekends and a weekday name', () => {
    expect(ids('gantt\n    excludes weekends\n    excludes sunday', 'gantt')).toEqual([])
  })

  test('flags a reference to a task id that does not exist', () => {
    expect(ids('gantt\n    A :a1, 2026-01-01, 3d\n    B :after nope, 2d', 'gantt')).toContain(
      'gantt/unknown-task',
    )
  })

  test('accepts a reference to a declared task id', () => {
    expect(ids('gantt\n    A :a1, 2026-01-01, 3d\n    B :after a1, 2d', 'gantt')).toEqual([])
  })
})

describe('pie', () => {
  test('flags zero and negative values', () => {
    expect(ids('pie\n"a" : 0', 'pie')).toEqual(['pie/non-positive-value'])
    expect(ids('pie\n"a" : -3', 'pie')).toEqual(['pie/non-positive-value'])
  })

  test('flags more than two decimal places', () => {
    expect(ids('pie\n"a" : 1.2345', 'pie')).toEqual(['pie/precision'])
  })
})

describe('venn', () => {
  test('flags a union referencing an undeclared set', () => {
    expect(ids('venn-beta\n  set A\n  union A,B["AB"]', 'venn')).toEqual(['venn/unknown-set'])
  })

  test('accepts a union of declared sets', () => {
    expect(ids('venn-beta\n  set A\n  set B\n  union A,B["AB"]', 'venn')).toEqual([])
  })
})

describe('coordinate ranges', () => {
  test('flags a quadrant point outside 0 to 1', () => {
    expect(ids('quadrantChart\n  A: [1.4, 0.2]', 'quadrant')).toEqual(['quadrant/out-of-range'])
  })

  test('flags a wardley coordinate outside 0 to 1', () => {
    expect(ids('wardley-beta\ncomponent A [1.2, 0.5]', 'wardley')).toEqual([
      'wardley/out-of-range',
    ])
  })

  test('does not treat the wardley size directive as a coordinate', () => {
    expect(ids('wardley-beta\nsize [1100, 600]', 'wardley')).toEqual([])
  })
})

describe('cynefin', () => {
  test('flags an unknown domain', () => {
    expect(ids('cynefin-beta\n  simple --> clear', 'cynefin')).toEqual(['cynefin/unknown-domain'])
  })

  test('flags a self-loop, which is silently ignored', () => {
    expect(ids('cynefin-beta\n  complex --> complex', 'cynefin')).toEqual(['cynefin/self-loop'])
  })
})

describe('other dialects', () => {
  test('flags a kanban priority outside the allowed four', () => {
    expect(ids("kanban\n  a[A]\n    b[B]@{ priority: 'Medium' }", 'kanban')).toEqual([
      'kanban/priority',
    ])
  })

  test('flags a per-point label on a bar, which is ignored', () => {
    expect(ids('xychart\n    bar [12 "one", 20]', 'xychart')).toEqual(['xychart/bar-label'])
  })

  test('flags a sankey row without three columns', () => {
    expect(ids('sankey\n\na,b', 'sankey')).toEqual(['sankey/columns'])
  })

  test('accepts a sankey row whose label contains a quoted comma', () => {
    expect(ids('sankey\n\nPumped heat,"Heating, homes",193.026', 'sankey')).toEqual([])
  })

  test('flags a negative treemap value', () => {
    expect(ids('treemap-beta\n"A": -5', 'treemap')).toEqual(['treemap/negative-value'])
  })

  test('flags an unknown radar graticule', () => {
    expect(ids('radar-beta\n  graticule square', 'radar')).toEqual(['radar/graticule'])
  })

  test('flags the wrong choice operator per railroad notation', () => {
    expect(ids('railroad-ebnf-beta\nsign = "+" / "-" ;', 'railroad')).toEqual([
      'railroad/wrong-choice-operator',
    ])
    expect(ids('railroad-abnf-beta\nsign = "+" | "-" ;', 'railroad')).toEqual([
      'railroad/wrong-choice-operator',
    ])
  })

  test('ignores a choice character inside a terminal string', () => {
    expect(ids('railroad-ebnf-beta\npipe = "/" ;', 'railroad')).toEqual([])
  })
})

describe('reported positions', () => {
  test('lines are 1-based and columns point at the offending token', () => {
    const [diagnostic] = diagnose('pie\n"a" : -3', 'pie')
    expect(diagnostic?.line).toBe(2)
    expect(diagnostic?.from).toBe(6)
    expect(diagnostic?.severity).toBe('error')
  })
})

