end = next(i for i, l in enumerate(lines) if l.strip() == '}, [error])')

new_block = """  // Rule findings and the render error share the gutter. Neither ever clears the preview.
  useEffect(() => {
    const instance = view.current
    if (!instance) return
    const doc = instance.state.doc
    const clamp = (line: number) => Math.min(Math.max(line, 1), doc.lines)

    const items = diagnostics.map((finding) => {
      const line = doc.line(clamp(finding.line))
      return {
        from: Math.min(line.from + finding.from, line.to),
        to: Math.min(line.from + finding.to, line.to),
        severity: finding.severity,
        message: finding.message,
        source: finding.ruleId,
      }
    })

    if (error) {
      const line = doc.line(clamp(error.line ?? 1))
      items.push({
        from: error.column !== undefined ? Math.min(line.from + error.column, line.to) : line.from,
        to: line.to,
        severity: 'error' as const,
        message: error.message,
        source: 'mermaid',
      })
    }

    instance.dispatch(setDiagnostics(instance.state, items))
  }, [error, diagnostics])""".split('\n')

lines[start:end + 1] = new_block
t = '\n'.join(lines)
t = t.replace("import { getDialect, mermaidCompletion } from '@mr/editor'",
              "import { type EditorDiagnostic, getDialect, mermaidCompletion } from '@mr/editor'", 1)
t = t.replace("""  /** Normalized parse/render error, placed on its line in the gutter. */
  error: RenderError | null
}""", """  /** Normalized parse/render error, placed on its line in the gutter. */
  error: RenderError | null
  /** Rule-based findings for the current dialect. */
  diagnostics: readonly EditorDiagnostic[]
}""", 1)
t = t.replace("export function CodeEditor({ value, onChange, typeId, error }: Props) {",
              "export function CodeEditor({ value, onChange, typeId, error, diagnostics }: Props) {", 1)
p.write_text(t)
print('code-editor patched')
PY
