import { resetColorCache } from '@mr/ui'
import { useCallback, useEffect, useState } from 'react'
import { getWorkspace } from './workspace'

/**
 * Light and dark, from the one token set.
 *
 * Switching the theme must also invalidate the resolved colour cache and force a
 * re-render, or the diagram keeps the previous palette while the chrome changes — the
 * exact "pasted in from another product" look the token bridge exists to prevent.
 */

export type Theme = 'light' | 'dark'

const PREFERENCE_KEY = 'theme'

function apply(theme: Theme): void {
  document.documentElement.classList.toggle('dark', theme === 'dark')
  resetColorCache()
}

function systemTheme(): Theme {
  return window.matchMedia?.('(prefers-color-scheme: light)').matches ? 'light' : 'dark'
}

export function useTheme(): { theme: Theme; toggle: () => void } {
  const [theme, setTheme] = useState<Theme>(() =>
    document.documentElement.classList.contains('dark') ? 'dark' : 'light',
  )

  // Stored preference wins over the class the HTML shipped with; system preference is the
  // fallback, so a first-time visitor gets what their OS asked for.
  useEffect(() => {
    void (async () => {
      try {
        const workspace = await getWorkspace()
        const stored = await workspace.preferences.get<Theme>(PREFERENCE_KEY)
        const next = stored ?? systemTheme()
        apply(next)
        setTheme(next)
      } catch {
        // Storage unavailable: keep whatever the document already has.
      }
    })()
  }, [])

  const toggle = useCallback(() => {
    setTheme((previous) => {
      const next: Theme = previous === 'dark' ? 'light' : 'dark'
      apply(next)
      void getWorkspace()
        .then((workspace) => workspace.preferences.set(PREFERENCE_KEY, next))
        .catch(() => undefined)
      return next
    })
  }, [])

  return { theme, toggle }
}

