import { type DiagramDocument, getDiagramType } from '@mr/core'
import {
  Button,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  Input,
} from '@mr/ui'
import { useEffect, useMemo, useState } from 'react'
import { getWorkspace } from '../lib/workspace'

interface Props {
  currentId: string | null
  onOpen: (document: DiagramDocument) => void
  onClose: () => void
}

function relativeTime(timestamp: number, now: number): string {
  const seconds = Math.round((now - timestamp) / 1000)
  if (seconds < 60) return 'just now'
  const minutes = Math.round(seconds / 60)
  if (minutes < 60) return `${minutes} min ago`
  const hours = Math.round(minutes / 60)
  if (hours < 24) return `${hours} h ago`
  return `${Math.round(hours / 24)} d ago`
}

/**
 * The diagram library.
 *
 * Without this the workspace is write-only: everything is saved and nothing can be
 * reopened. Deletion is soft, so a mis-click is recoverable.
 */
export function LibraryDialog({ currentId, onOpen, onClose }: Props) {
  const [documents, setDocuments] = useState<DiagramDocument[] | null>(null)
  const [query, setQuery] = useState('')
  const [showDeleted, setShowDeleted] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const now = useMemo(() => Date.now(), [])

  async function reload(includeDeleted = showDeleted) {
    try {
      const workspace = await getWorkspace()
      const page = await workspace.documents.list({ includeDeleted })
      setDocuments([...page.items])
      setError(null)
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : 'Could not read the library.')
    }
  }

  useEffect(() => {
    void reload(showDeleted)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showDeleted])

  const matches = useMemo(() => {
    const needle = query.trim().toLowerCase()
    return (documents ?? []).filter(
      (doc) => needle === '' || doc.name.toLowerCase().includes(needle),
    )
  }, [documents, query])

  async function remove(id: string) {
    const workspace = await getWorkspace()
    await workspace.documents.delete(id)
    await reload()
  }

  async function restore(id: string) {
    const workspace = await getWorkspace()
    await workspace.documents.restore(id)
    await reload()
  }

  return (
    <Dialog open onOpenChange={(next) => !next && onClose()}>
      <DialogContent className="flex max-h-[75vh] flex-col sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>Diagrams</DialogTitle>
        </DialogHeader>

        <div className="flex items-center gap-2">
          <Input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search by name…"
            aria-label="Search diagrams"
          />
          <Button
            variant={showDeleted ? 'secondary' : 'ghost'}
            size="sm"
            onClick={() => setShowDeleted((value) => !value)}
          >
            {showDeleted ? 'Hide deleted' : 'Show deleted'}
          </Button>
        </div>

        {error && <p className="text-danger text-xs">{error}</p>}

        <ul className="-mx-2 min-h-0 flex-1 overflow-auto px-2">
          {documents === null && (
            <li className="py-8 text-center text-muted-foreground text-sm">Loading…</li>
          )}
          {documents !== null && matches.length === 0 && (
            <li className="py-8 text-center text-muted-foreground text-sm">
              {query ? `Nothing matches “${query}”.` : 'No diagrams yet.'}
            </li>
          )}
          {matches.map((doc) => {
            const type = doc.typeId ? getDiagramType(doc.typeId) : undefined
            const isCurrent = doc.id === currentId
            return (
              <li
                key={doc.id}
                className="flex items-center gap-2 rounded-app px-2 py-2 hover:bg-muted"
              >
                <button
                  type="button"
                  onClick={() => onOpen(doc)}
                  className="flex min-w-0 flex-1 items-baseline gap-2 text-left"
                >
                  <span className={`truncate text-sm ${doc.deletedAt ? 'line-through' : ''}`}>
                    {doc.name}
                  </span>
                  <span className="shrink-0 text-muted-foreground text-xs">
                    {type?.label ?? 'Unrecognised'}
                  </span>
                  {isCurrent && <span className="shrink-0 text-primary text-xs">open</span>}
                  <span className="ml-auto shrink-0 tabular-nums text-muted-foreground text-xs">
                    {relativeTime(doc.updatedAt, now)}
                  </span>
                </button>
                {doc.deletedAt ? (
                  <Button variant="ghost" size="sm" onClick={() => void restore(doc.id)}>
                    Restore
                  </Button>
                ) : (
                  <Button
                    variant="ghost"
                    size="sm"
                    disabled={isCurrent}
                    onClick={() => void remove(doc.id)}
                  >
                    Delete
                  </Button>
                )}
              </li>
            )
          })}
        </ul>
      </DialogContent>
    </Dialog>
  )
}

