/**
 * The bridge between the application token set and Mermaid's theme variables.
 *
 * Both sides read from the CSS variables declared in styles.css, so switching to dark
 * mode moves the interface and the diagram together, from the same source values. This
 * file is the only place allowed to know Mermaid's variable names.
 *
 * Reference: `mermaid-upstream/packages/mermaid/src/docs/config/theming.md`.
 *
 * Two rules from that page shape the whole design:
 *
 * 1. *"The theming engine will only recognize hex colors and not color names"*
 *    (`theming.md:92`). Every value here is converted to hex, never `rgb()` or `oklch()`.
 * 2. Most variables are **derived**: `primaryBorderColor` from `primaryColor`, `lineColor`
 *    from `background`, and so on, with `darkMode` deciding whether derivation lightens or
 *    darkens. So the job is to set the primaries correctly and let Mermaid derive the rest,
 *    not to enumerate a hundred variables and fight the engine.
 */

export type ThemeVariables = Record<string, string | Record<string, string>>

/**
 * Converts a CSS color into hex.
 *
 * Neither `getComputedStyle` nor `canvas.fillStyle` does this on its own: both preserve
 * the color space under CSS Color 4, so an `oklch` token comes back as `oklch` from both.
 * The only reliable browser-native conversion is to paint the color and read the pixel,
 * which forces the compositor to resolve it into sRGB bytes.
 */
const colorCache = new Map<string, string>()

function toHex(value: string): string {
  const cached = colorCache.get(value)
  if (cached !== undefined) return cached

  const canvas = document.createElement('canvas')
  canvas.width = 1
  canvas.height = 1
  const context = canvas.getContext('2d', { willReadFrequently: true })
  if (!context) return value

  let result = value
  try {
    context.clearRect(0, 0, 1, 1)
    context.fillStyle = value
    context.fillRect(0, 0, 1, 1)
    const [r, g, b] = context.getImageData(0, 0, 1, 1).data
    if (r !== undefined && g !== undefined && b !== undefined) {
      result = `#${[r, g, b].map((channel) => channel.toString(16).padStart(2, '0')).join('')}`
    }
  } catch {
    // An unpaintable value stays as it was; mermaid will report it rather than us guessing.
  }

  colorCache.set(value, result)
  return result
}

/** Clears the conversion cache. Call when the theme changes. */
export function resetColorCache(): void {
  colorCache.clear()
}

interface Tokens {
  read(name: string): string
  color(name: string): string
}

function tokensFor(scope: Element): Tokens {
  const styles = getComputedStyle(scope)
  const read = (name: string) => styles.getPropertyValue(name).trim()
  return { read, color: (name: string) => toHex(read(name)) }
}

/**
 * The eight categorical slots, in fixed order.
 *
 * Assigned in order and never cycled: a ninth series is not a generated hue. Mermaid
 * consumes them under several names — `pie1..12` for pie sections, `cScale0..11` for radar
 * curves and timeline sections, `fillType0..7` for user-journey sections — and each of
 * those lists is longer than eight, so the tail repeats deliberately rather than
 * inventing colors.
 */
function seriesPalette(tokens: Tokens): string[] {
  return Array.from({ length: 8 }, (_, index) => tokens.color(`--chart-${index + 1}`))
}

function repeat(palette: string[], count: number, prefix: string, start = 1): ThemeVariables {
  const variables: ThemeVariables = {}
  for (let index = 0; index < count; index++) {
    variables[`${prefix}${index + start}`] = palette[index % palette.length] as string
  }
  return variables
}

/**
 * Resolves the current token values into Mermaid `themeVariables`.
 *
 * @param isDark whether the diagram should be derived for a dark surface. This is not
 * cosmetic: `darkMode` decides the direction of every derived color, so getting it wrong
 * leaves roughly forty variables computed for the opposite background.
 */
export function mermaidThemeVariables(
  isDark: boolean,
  scope: Element = document.documentElement,
): ThemeVariables {
  const tokens = tokensFor(scope)
  const palette = seriesPalette(tokens)

  const background = tokens.color('--diagram-background')
  const node = tokens.color('--diagram-node')
  const nodeBorderColor = tokens.color('--diagram-node-border')
  const line = tokens.color('--diagram-line')
  const text = tokens.color('--diagram-text')
  const cluster = tokens.color('--diagram-cluster')
  const border = tokens.color('--border')
  const muted = tokens.color('--muted')
  const mutedText = tokens.color('--muted-foreground')
  const surface = tokens.color('--surface-raised')
  const accent = tokens.color('--accent')
  const danger = tokens.color('--danger')
  const warning = tokens.color('--warning')

  return {
    // Derivation control. Everything below leans on this being right.
    darkMode: String(isDark),

    // Primaries. Mermaid derives borders, text and secondary/tertiary from these.
    background,
    primaryColor: node,
    primaryBorderColor: nodeBorderColor,
    primaryTextColor: text,
    secondaryColor: muted,
    tertiaryColor: cluster,
    lineColor: line,
    textColor: text,
    mainBkg: node,

    fontFamily: tokens.read('--font-sans'),
    fontSize: '14px',

    // Flowchart
    nodeBorder: nodeBorderColor,
    nodeTextColor: text,
    clusterBkg: cluster,
    clusterBorder: border,
    defaultLinkColor: line,
    titleColor: text,
    edgeLabelBackground: background,

    // Notes, shared by several diagram types
    noteBkgColor: surface,
    noteTextColor: text,
    noteBorderColor: border,

    // Sequence
    actorBkg: node,
    actorBorder: nodeBorderColor,
    actorTextColor: text,
    actorLineColor: line,
    signalColor: line,
    signalTextColor: text,
    labelBoxBkgColor: muted,
    labelBoxBorderColor: border,
    labelTextColor: text,
    loopTextColor: text,
    activationBkgColor: accent,
    activationBorderColor: nodeBorderColor,
    sequenceNumberColor: background,

    // State and class
    labelColor: text,
    altBackground: cluster,
    classText: text,

    // Error surface
    errorBkgColor: danger,
    errorTextColor: background,

    // Pie. Its stroke and legend colors default to literal `black`, which is unreadable
    // on a dark surface, so they are set explicitly rather than left to derivation.
    ...repeat(palette, 12, 'pie'),
    pieStrokeColor: background,
    pieOuterStrokeColor: border,
    pieTitleTextColor: text,
    pieSectionTextColor: text,
    pieLegendTextColor: mutedText,
    pieOpacity: '1',

    // Radar curves, timeline sections and anything else on the generic colour scale.
    ...repeat(palette, 12, 'cScale', 0),

    // User journey sections.
    ...repeat(palette, 8, 'fillType', 0),

    // Per-diagram namespaces. Each of these has hardcoded light-theme defaults upstream.
    radar: {
      axisColor: border,
      axisLabelFontSize: '12px',
      curveOpacity: '0.6',
      curveStrokeWidth: '2',
      graticuleColor: border,
      graticuleOpacity: '0.4',
      legendFontSize: '13px',
    },
    xyChart: {
      backgroundColor: background,
      titleColor: text,
      dataLabelColor: text,
      legendTextColor: mutedText,
      xAxisLabelColor: mutedText,
      xAxisTitleColor: text,
      xAxisTickColor: border,
      xAxisLineColor: border,
      yAxisLabelColor: mutedText,
      yAxisTitleColor: text,
      yAxisTickColor: border,
      yAxisLineColor: border,
      plotColorPalette: palette.join(', '),
    },
    cynefin: {
      complexBg: cluster,
      complicatedBg: muted,
      clearBg: cluster,
      chaoticBg: muted,
      confusionBg: surface,
      boundaryColor: border,
      cliffColor: warning,
      arrowColor: line,
      labelColor: text,
      textColor: mutedText,
    },
    // treeView defaults to literal `black` for labels and connector lines, which makes it
    // unreadable in dark mode. This is the type that needs the bridge most.
    treeView: {
      labelColor: text,
      lineColor: line,
      iconColor: mutedText,
      descriptionColor: mutedText,
      highlightStroke: accent,
    },
  }
}

/** Mermaid's own base theme that best matches ours, before our variables are applied. */
export function mermaidBaseTheme(isDark: boolean): 'base' | 'dark' {
  return isDark ? 'dark' : 'base'
}

