import { Document, isMap, parseDocument } from 'yaml'

/**
 * Reading and writing the diagram's YAML frontmatter.
 *
 * Styling lives in the document, not in a settings panel beside it. `config:` in the
 * frontmatter is mermaid's own mechanism — *"The entire mermaid configuration (except the
 * secure configs) can be overridden by the diagram author in the frontmatter"*
 * (`mermaid-upstream/packages/mermaid/src/docs/config/configuration.md`) — so anything the
 * user changes here travels with the text: it exports, it shares, it survives a paste into
 * someone else's editor.
 *
 * Edits go through the YAML Document API rather than string surgery, so the user's
 * existing keys, ordering and comments are preserved. A style panel must never reformat a
 * document the user hand-wrote.
 */

const FRONTMATTER = /^(\s*---\r?\n)([\s\S]*?)(\r?\n---[ \t]*\r?\n?)/

export interface Frontmatter {
  /** Raw YAML between the `---` fences, or null when there is no frontmatter. */
  readonly yaml: string | null
  /** Character offsets of the YAML body inside the document. */
  readonly range: { from: number; to: number } | null
  /** The diagram source after the frontmatter. */
  readonly body: string
}

export function readFrontmatter(text: string): Frontmatter {
  const match = FRONTMATTER.exec(text)
  if (!match) return { yaml: null, range: null, body: text }
  const open = match[1] as string
  const yaml = match[2] as string
  const from = open.length
  return { yaml, range: { from, to: from + yaml.length }, body: text.slice(match[0].length) }
}

/** A dotted path into the config map, e.g. `themeVariables.primaryColor`. */
export type ConfigPath = string

function pathParts(path: ConfigPath): string[] {
  return ['config', ...path.split('.')]
}

/** Reads a single config value, or undefined when it is not set. */
export function readConfigValue(text: string, path: ConfigPath): string | undefined {
  const { yaml } = readFrontmatter(text)
  if (yaml === null) return undefined
  const doc = parseDocument(yaml)
  if (doc.errors.length > 0) return undefined
  const value = doc.getIn(pathParts(path))
  return typeof value === 'string' || typeof value === 'number' ? String(value) : undefined
}

/** Every config value currently set, flattened to dotted paths. */
export function readConfig(text: string): Record<string, string> {
  const { yaml } = readFrontmatter(text)
  if (yaml === null) return {}
  const doc = parseDocument(yaml)
  if (doc.errors.length > 0) return {}
  const config = doc.get('config')
  const flat: Record<string, string> = {}

  const walk = (node: unknown, prefix: string) => {
    if (!isMap(node)) return
    for (const item of node.items) {
      const key = String((item.key as { value?: unknown })?.value ?? item.key)
      const value = item.value as { value?: unknown } | null
      const nested = prefix === '' ? key : `${prefix}.${key}`
      if (isMap(value)) walk(value, nested)
      else if (value && (typeof value.value === 'string' || typeof value.value === 'number')) {
        flat[nested] = String(value.value)
      }
    }
  }

  walk(config, '')
  return flat
}

/**
 * Sets or removes a config value and returns the new document text.
 *
 * Passing `undefined` removes the key, and prunes any map it leaves empty — including the
 * whole `config:` block and the frontmatter fences. Resetting to the theme should leave no
 * residue behind.
 */
export function writeConfigValue(
  text: string,
  path: ConfigPath,
  value: string | undefined,
): string {
  const { yaml, range, body } = readFrontmatter(text)
  const doc = yaml === null ? new Document({}) : parseDocument(yaml)
  if (doc.errors.length > 0) return text

  const parts = pathParts(path)

  if (value === undefined) {
    doc.deleteIn(parts)
    // Prune empty ancestors so removing the last override removes the block.
    for (let depth = parts.length - 1; depth > 0; depth--) {
      const parent = doc.getIn(parts.slice(0, depth))
      if (isMap(parent) && parent.items.length === 0) doc.deleteIn(parts.slice(0, depth))
      else break
    }
  } else {
    doc.setIn(parts, value)
  }

  const contents = doc.contents
  const isEmpty = !isMap(contents) || contents.items.length === 0
  if (isEmpty) return body

  const serialized = doc.toString({ lineWidth: 0 }).replace(/\n$/, '')
  if (range === null) return `---\n${serialized}\n---\n${body}`
  return `${text.slice(0, range.from)}${serialized}${text.slice(range.to)}`
}

/** Applies several changes in one pass, so the editor sees a single edit. */
export function writeConfigValues(
  text: string,
  changes: Readonly<Record<ConfigPath, string | undefined>>,
): string {
  let result = text
  for (const [path, value] of Object.entries(changes)) {
    result = writeConfigValue(result, path, value)
  }
  return result
}

