import { describe, expect, test } from 'bun:test'
import { readConfig, readConfigValue, readFrontmatter, writeConfigValue } from './frontmatter'
import { detectDiagramType } from './detect'
import { CURVE_OPTION, optionsFor } from './styling'

const WITH_FRONTMATTER = `---
title: Order flow
config:
  look: handDrawn
  flowchart:
    curve: linear
  themeVariables:
    primaryColor: "#ff0000"
---
flowchart TD
    A --> B
`

describe('readFrontmatter', () => {
  test('separates the yaml from the body', () => {
    const { yaml, body } = readFrontmatter(WITH_FRONTMATTER)
    expect(yaml).toContain('title: Order flow')
    expect(body).toBe('flowchart TD\n    A --> B\n')
  })

  test('returns the whole document when there is no frontmatter', () => {
    const text = 'flowchart TD\n    A --> B\n'
    expect(readFrontmatter(text)).toEqual({ yaml: null, range: null, body: text })
  })

  test('does not mistake a --- inside the body for frontmatter', () => {
    const text = 'stateDiagram-v2\n  [*] --> Still\n'
    expect(readFrontmatter(text).yaml).toBeNull()
  })
})

describe('readConfigValue', () => {
  test('reads a nested value', () => {
    expect(readConfigValue(WITH_FRONTMATTER, 'flowchart.curve')).toBe('linear')
    expect(readConfigValue(WITH_FRONTMATTER, 'themeVariables.primaryColor')).toBe('#ff0000')
    expect(readConfigValue(WITH_FRONTMATTER, 'look')).toBe('handDrawn')
  })

  test('returns undefined for a value that is not set', () => {
    expect(readConfigValue(WITH_FRONTMATTER, 'themeVariables.lineColor')).toBeUndefined()
    expect(readConfigValue('flowchart TD\n A --> B', 'look')).toBeUndefined()
  })

  test('survives malformed yaml rather than throwing', () => {
    expect(readConfigValue('---\nconfig: [unclosed\n---\nflowchart TD', 'look')).toBeUndefined()
  })
})

describe('readConfig', () => {
  test('flattens every set value to a dotted path', () => {
    expect(readConfig(WITH_FRONTMATTER)).toEqual({
      look: 'handDrawn',
      'flowchart.curve': 'linear',
      'themeVariables.primaryColor': '#ff0000',
    })
  })

  test('is empty when nothing is configured', () => {
    expect(readConfig('flowchart TD\n A --> B')).toEqual({})
  })
})

describe('writeConfigValue', () => {
  test('adds frontmatter to a document that has none', () => {
    const next = writeConfigValue('flowchart TD\n    A --> B\n', 'flowchart.curve', 'linear')
    expect(readConfigValue(next, 'flowchart.curve')).toBe('linear')
    expect(detectDiagramType(next)?.id).toBe('flowchart')
  })

  test('keeps the diagram body byte for byte', () => {
    const body = 'flowchart TD\n    A --> B\n'
    const next = writeConfigValue(body, 'look', 'handDrawn')
    expect(readFrontmatter(next).body).toBe(body)
  })

  test('preserves unrelated frontmatter keys', () => {
    const next = writeConfigValue(WITH_FRONTMATTER, 'themeVariables.lineColor', '#00ff00')
    expect(readConfigValue(next, 'title' as never)).toBeUndefined()
    expect(next).toContain('title: Order flow')
    expect(readConfigValue(next, 'look')).toBe('handDrawn')
    expect(readConfigValue(next, 'themeVariables.primaryColor')).toBe('#ff0000')
    expect(readConfigValue(next, 'themeVariables.lineColor')).toBe('#00ff00')
  })

  test('overwrites an existing value in place', () => {
    const next = writeConfigValue(WITH_FRONTMATTER, 'flowchart.curve', 'stepBefore')
    expect(readConfigValue(next, 'flowchart.curve')).toBe('stepBefore')
    expect(next.match(/curve:/g)).toHaveLength(1)
  })

  test('removing a value prunes the map it emptied', () => {
    const next = writeConfigValue(WITH_FRONTMATTER, 'flowchart.curve', undefined)
    expect(readConfigValue(next, 'flowchart.curve')).toBeUndefined()
    expect(next).not.toContain('flowchart:')
    expect(readConfigValue(next, 'look')).toBe('handDrawn')
  })

  test('removing the last override removes the frontmatter entirely', () => {
    const one = writeConfigValue('flowchart TD\n    A --> B\n', 'look', 'handDrawn')
    const none = writeConfigValue(one, 'look', undefined)
    expect(none).toBe('flowchart TD\n    A --> B\n')
    expect(readFrontmatter(none).yaml).toBeNull()
  })

  test('the result still parses as the same diagram type', () => {
    for (const value of ['linear', 'stepBefore', 'basis']) {
      const next = writeConfigValue('flowchart TD\n    A --> B\n', 'flowchart.curve', value)
      expect(detectDiagramType(next)?.id).toBe('flowchart')
    }
  })
})

describe('styling options', () => {
  test('straight lines are offered, because that is what people ask for', () => {
    expect(CURVE_OPTION.choices.map((c) => c.value)).toContain('linear')
  })

  test('curve is offered only for the flowchart family', () => {
    expect(optionsFor('flowchart').map((o) => o.path)).toContain('flowchart.curve')
    expect(optionsFor('pie').map((o) => o.path)).not.toContain('flowchart.curve')
  })

  test('look applies to every diagram type', () => {
    expect(optionsFor('pie').map((o) => o.path)).toContain('look')
    expect(optionsFor(null).map((o) => o.path)).toContain('look')
  })
})

