import {
  STYLE_COLORS,
  type StyleOption,
  optionsFor,
  readConfig,
  writeConfigValue,
} from '@mr/core'
import { Button, Separator, tokenColor } from '@mr/ui'
import { RotateCcwIcon, XIcon } from 'lucide-react'
import { useMemo } from 'react'

interface Props {
  text: string
  typeId: string | null
  onChange: (next: string) => void
  onClose: () => void
}

/** The token each colour falls back to when the document has no override. */
const COLOR_FALLBACK: Record<string, string> = {
  'themeVariables.primaryColor': '--diagram-node',
  'themeVariables.primaryBorderColor': '--diagram-node-border',
  'themeVariables.primaryTextColor': '--diagram-text',
  'themeVariables.lineColor': '--diagram-line',
}

/**
 * Styling, written into the document's own frontmatter.
 *
 * Nothing here is stored beside the diagram: every control edits `config:` in the YAML
 * frontmatter, which is mermaid's own mechanism. So a styled diagram exports styled, and
 * pastes into any other Mermaid editor still styled. The document stays the source of
 * truth — if it could not round-trip to text, it would not ship.
 */
export function StylePanel({ text, typeId, onChange, onClose }: Props) {
  const config = useMemo(() => readConfig(text), [text])
  const options = useMemo(() => optionsFor(typeId), [typeId])
  const overrides = Object.keys(config).length

  const set = (path: string, value: string | undefined) =>
    onChange(writeConfigValue(text, path, value))

  return (
    <aside
      className="flex w-72 shrink-0 flex-col overflow-y-auto border-l bg-surface"
      aria-label="Diagram style"
    >
      <header className="flex h-11 shrink-0 items-center gap-2 border-b px-3">
        <span className="font-medium text-sm">Style</span>
        {overrides > 0 && (
          <span className="text-muted-foreground text-xs">
            {overrides} {overrides === 1 ? 'override' : 'overrides'}
          </span>
        )}
        <Button variant="ghost" size="icon" className="ml-auto" onClick={onClose} aria-label="Close style panel">
          <XIcon className="size-4" />
        </Button>
      </header>

      <div className="flex flex-col gap-5 p-3">
        <section className="flex flex-col gap-2">
          <h3 className="font-medium text-xs">Colours</h3>
          {STYLE_COLORS.map((color) => {
            const override = config[color.path]
            const fallbackToken = COLOR_FALLBACK[color.path] ?? '--diagram-node'
            const shown = override ?? tokenColor(fallbackToken)
            return (
              <div key={color.path} className="flex items-center gap-2">
                <input
                  type="color"
                  value={shown}
                  onChange={(event) => set(color.path, event.target.value)}
                  aria-label={color.label}
                  className="size-7 shrink-0 cursor-pointer rounded-app border bg-transparent"
                />
                <label className="min-w-0 flex-1">
                  <span className="block text-sm">{color.label}</span>
                  <span className="block truncate text-muted-foreground text-xs">
                    {override ?? 'From theme'}
                  </span>
                </label>
                {override && (
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => set(color.path, undefined)}
                    aria-label={`Reset ${color.label} to theme`}
                  >
                    <RotateCcwIcon className="size-3.5" />
                  </Button>
                )}
              </div>
            )
          })}
          <p className="text-muted-foreground text-xs">
            Mermaid derives border and text shades from the fill unless you set them too.
          </p>
        </section>

        <Separator />

        {options.map((option: StyleOption) => {
          const current = config[option.path] ?? ''
          return (
            <section key={option.path} className="flex flex-col gap-1.5">
              <div className="flex items-baseline gap-2">
                <h3 className="font-medium text-xs">{option.label}</h3>
                {current !== '' && (
                  <button
                    type="button"
                    className="ml-auto text-muted-foreground text-xs hover:text-foreground"
                    onClick={() => set(option.path, undefined)}
                  >
                    Reset
                  </button>
                )}
              </div>
              <select
                value={current}
                onChange={(event) =>
                  set(option.path, event.target.value === '' ? undefined : event.target.value)
                }
                aria-label={option.label}
                className="rounded-app border bg-transparent px-2 py-1.5 text-sm"
              >
                <option value="">Default</option>
                {option.choices.map((choice) => (
                  <option key={choice.value} value={choice.value}>
                    {choice.label}
                  </option>
                ))}
              </select>
              <p className="text-muted-foreground text-xs">{option.help}</p>
            </section>
          )
        })}

        {overrides > 0 && (
          <>
            <Separator />
            <section className="flex flex-col gap-2">
              <p className="text-muted-foreground text-xs">
                These are written into the diagram's frontmatter, so they travel with the
                text when you export or share it.
              </p>
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  let next = text
                  for (const path of Object.keys(config)) next = writeConfigValue(next, path, undefined)
                  onChange(next)
                }}
              >
                Reset all to theme
              </Button>
            </section>
          </>
        )}
      </div>
    </aside>
  )
}

