// 1. Primer uso de cada tipo: mermaid carga un módulo por tipo bajo demanda.
console.log('--- primer render por tipo (carga perezosa) ---')
for (const [name, src] of [
  ['sequence', 'sequenceDiagram\n  A->>B: hola\n  B-->>A: adios'],
  ['gantt', 'gantt\n  title X\n  dateFormat YYYY-MM-DD\n  section S\n  A :a1, 2026-01-01, 5d'],
  ['class', 'classDiagram\n  class A {\n +x int\n }\n  A <|-- B'],
  ['git', 'gitGraph\n  commit\n  branch dev\n  commit\n  checkout main\n  merge dev'],
]) {
  const r = waitRender(); await setText(src); console.log(' ', name.padEnd(10), JSON.stringify(await r))
}

// 2. Diagramas grandes: la promesa del producto.
console.log('--- diagramas grandes ---')
for (const n of [200, 600, 1500]) {
  const lines = ['flowchart TD']
  for (let i = 0; i < n; i++) lines.push(`  N${i}[Nodo ${i}] --> N${i+1}`)
  const r = waitRender(); await setText(lines.join('\n')); console.log(' ', String(n).padStart(5), 'nodos', JSON.stringify(await r))
}

// 3. Pan y zoom sobre el diagrama grande que quedó en pantalla.
const fps = await p.evaluate(() => new Promise((res) => {
  const el = document.querySelector('[data-testid="diagram-canvas"]')
  let frames = 0, x = 200
  const t0 = performance.now()
  const count = () => { frames++; if (performance.now()-t0 < 1500) requestAnimationFrame(count); else res(Math.round(frames/((performance.now()-t0)/1000))) }
  requestAnimationFrame(count)
  el.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, clientX: x, clientY: 300, button: 0 }))
  const id = setInterval(() => { x += 4; el.dispatchEvent(new PointerEvent('pointermove', { bubbles: true, clientX: x, clientY: 300 })) }, 16)
  setTimeout(() => { clearInterval(id); el.dispatchEvent(new PointerEvent('pointerup', { bubbles: true })) }, 1500)
}))
console.log('--- arrastre sobre el diagrama grande:', fps, 'fps')
await b.close()
EOF
